def build_posts() -> list[dict]:
    posts: list[dict] = []
    for category, topics in TOPICS.items():
        profile = CATEGORIES[category]
        for idx, item in enumerate(topics, 1):
            slug = f"{profile['slug']}-{idx:02d}-{slugify(item['title'])}"
            publish = TODAY - timedelta(days=(len(posts) * 3))
            keywords = list(dict.fromkeys(item["keywords"] + [category, "張老師", "香港音樂課程", profile["local"]]))
            post = {
                "id": slug,
                "slug": slug,
                "number": idx,
                "url": f"blog/{slug}.html",
                "title": item["title"],
                "category": category,
                "categorySlug": profile["slug"],
                "focus": item["focus"],
                "pain": item["pain"],
                "method": item["method"],
                "keywords": keywords,
                "level": item["level"],
                "date": publish.isoformat(),
                "readTime": "4 分鐘",
                "color": profile["color"],
            }
            post["excerpt"] = article_excerpt(post)
            posts.append(post)
    return posts


def reader_group(post: dict) -> str:
    title = post["title"]
    if any(word in title for word in ["兒童", "家長", "小朋友", "親子", "學校"]):
        return "香港家長及兒童初學者"
    if "成人" in title:
        return "成人學生"
    if post["category"] == "考級":
        return "準備考級的學生和家長"
    if post["category"] == "空靈鼓":
        return "零基礎學員、親子活動參加者及成人興趣學生"
    if post["category"] == "簫":
        return "喜歡沉靜音色的成人學生及中樂愛好者"
    return "香港初學者、進階學生及家長"


def search_intent(post: dict) -> str:
    title = post["title"]
    if any(word in title for word in ["如何選", "怎樣選", "分別", "比較", "指南", "選購"]):
        return "比較型"
    if any(word in title for word in ["課程", "老師", "香港", "報考", "查詢"]):
        return "本地型"
    if any(word in title for word in ["考級", "伴奏", "模擬考", "報名"]):
        return "交易型"
    return "資訊型"


def article_scene(post: dict) -> str:
    category = post["category"]
    focus = plain_focus(post)
    title = post["title"]
    if any(word in title for word in ["選", "買", "第一支", "選購"]):
        if category == "長笛":
            return "很多家長第一次替孩子選長笛，最容易先看品牌、價錢和外觀。張老師通常會先看孩子的身高、手型、吹奏反應和日後保養安排，因為樂器合不合用，比外觀更重要。"
        if category in {"笛子", "簫"}:
            return f"第一次選{category}，不應只看外觀和價錢。張老師會先看手指距離、音準反應和學生想學的曲風，避免買到一支看起來漂亮、但實際上不適合練習的樂器。"
        if category == "空靈鼓":
            return "第一次買空靈鼓，不應只聽哪一款聲音最夢幻。張老師會先看調式、音域、用途和學生是否需要合奏，因為買錯調式，日後想練歌或合奏都會受限制。"
    if any(word in title for word in ["兒童", "家長", "小朋友"]):
        return f"家長最擔心的，是報讀後孩子是否真的有進步；一開始吹得好不好反而不是最要緊。張老師會先看{focus}，再判斷孩子適合用甚麼速度開始。"
    if "成人" in title:
        return f"成人學生最常遇到的問題，是想學但時間不穩定。張老師會先看{focus}，再把練習拆成短時間也做得到的步驟。"
    if category == "長笛":
        return f"學生拿起長笛試吹幾次，聲音有時出來，有時只剩氣聲。家長常以為是肺活量問題，張老師會先看{focus}，再判斷是否需要改嘴形、姿勢或練習方法。"
    if category == "笛子":
        return f"笛子很容易令人以為「吹得響就可以」。但一到樂句、笛膜和口風配合，{focus}就會把問題放大，聲音可能變散、變硬，甚至失去竹笛應有的語氣。"
    if category == "空靈鼓":
        return f"空靈鼓的聲音舒服，初學者很快有成功感。真正的難位多數在{focus}：拍子是否穩、留白是否清楚、左右手是否平均。"
    if category == "簫":
        return f"簫的第一個音往往要慢慢找。學生如果急着吹大聲，{focus}反而更難穩定；張老師會先讓學生聽到聲音核心，再談樂句和古曲味道。"
    return f"不少家長一談考級，就先問幾耐可以考。張老師通常會先看{focus}，因為考級不是只把曲目練熟，還要看音階、視奏、聽覺和上台穩定度。"


def image_brief(post: dict) -> list[dict]:
    category = post["category"]
    slug = post["categorySlug"]
    if category == "長笛":
        subject = "香港長笛課堂中，導師正在示範吹奏姿勢和呼吸方法"
        filename = "hong-kong-flute-lesson-beginner-breathing.png"
    elif category == "笛子":
        subject = "香港竹笛課堂中，導師正在示範口風、笛膜和手指位置"
        filename = "hong-kong-dizi-lesson-embouchure-dimo.png"
    elif category == "空靈鼓":
        subject = "香港空靈鼓課堂中，學員正在練習左右手節奏和簡單音型"
        filename = "hong-kong-tongue-drum-lesson-rhythm-practice.png"
    elif category == "簫":
        subject = "香港簫課堂中，導師正在示範長音、口風方向和安靜樂句"
        filename = "hong-kong-xiao-lesson-long-tone-practice.png"
    else:
        subject = "香港音樂考級課堂中，學生正在整理曲目、音階和視奏練習表"
        filename = "hong-kong-music-exam-lesson-practice-plan.png"
    return [
        {
            "type": "真相片優先",
            "use": "放在文章開首，讓讀者知道這是音樂課堂內容，不是罐頭教育文。",
            "alt": subject,
            "file": filename,
            "avoid": "不要用 AI 圖假裝真實學生或真實課堂。",
        },
        {
            "type": "半寫實插畫",
            "use": f"放在「張老師會先看哪裏」段落，解釋{post['focus']}。",
            "alt": f"{category}課堂中示範{post['focus']}的練習細節",
            "file": f"hong-kong-{slug}-{slugify(post['focus'])}-editorial-illustration.png",
            "avoid": "避免中文字、錯誤樂器結構、過度電影感光線。",
        },
    ]


def method_text(post: dict) -> str:
    method = post["method"].strip()
    return method


def method_tool(post: dict) -> str:
    method = method_text(post)
    if method.startswith("用"):
        return method[1:]
    return method


def topic_kind(post: dict) -> str:
    title = post["title"]
    if any(word in title for word in ["香港學", "一對一課堂", "課堂如何", "課堂應該"]):
        return "local"
    if any(word in title for word in ["選", "第一支", "買", "調式", "D調", "G調", "F調", "C大調"]):
        return "selection"
    if any(word in title for word in ["兒童", "家長", "親子", "小朋友", "學校"]):
        return "child"
    if "成人" in title:
        return "adult"
    if any(word in title for word in ["考級", "一級", "三級", "五級", "八級", "模擬考", "伴奏", "報考", "評分", "錄影"]):
        return "exam"
    if any(word in title for word in ["舞台", "演出", "緊張", "收音", "麥克風"]):
        return "stage"
    if any(word in title for word in ["保養", "防裂", "潮濕", "刮花", "清潔"]):
        return "care"
    if any(word in title for word in ["錄音", "日誌", "練習表", "自評"]):
        return "recording"
    if any(word in title for word in ["合奏", "鋼琴", "中西", "伴奏"]):
        return "ensemble"
    if any(word in title for word in ["氣息", "呼吸", "口型", "口風", "腹部", "吹不響"]):
        return "breath"
    if any(word in title for word in ["音準", "半孔", "轉調", "筒音", "視奏", "聽覺"]):
        return "pitch"
    if any(word in title for word in ["節奏", "拍子", "節拍器", "速度", "吐音", "手指"]):
        return "rhythm"
    if any(word in title for word in ["長音", "高音", "低音", "音色", "共鳴", "厚度"]):
        return "tone"
    if any(word in title for word in ["即興", "和弦", "旋律", "裝飾音", "滑音", "打音", "顫音", "Vibrato"]):
        return "expression"
    return "lesson"


def instrument_angle(post: dict) -> dict:
    category = post["category"]
    if category == "長笛":
        return {
            "lens": "銀色音色、氣息線條和手指協調",
            "observation": "長笛問題通常會在第一個音頭、換氣後第一拍，或高低音轉換時露出來。",
            "proof": "如果學生能在短句裏保持同一條氣流，後面練曲和考級都會穩得多。",
        }
    if category == "笛子":
        return {
            "lens": "口風、笛膜、筒音和民樂語氣",
            "observation": "笛子不是吹響就算好，笛膜聲、氣聲和手指裝飾都會直接影響一句旋律是否有味道。",
            "proof": "當學生聽得出笛膜太鬆、口風太散或滑音太重，練習就不再只是背指法。",
        }
    if category == "空靈鼓":
        return {
            "lens": "節奏呼吸、左右手分工和聲音留白",
            "observation": "空靈鼓最怕每個音都敲滿，聲音雖然舒服，但沒有拍子和句子就很快變成背景聲。",
            "proof": "當低音支點、旋律和停頓分得清楚，即使只用幾個音也可以有完整音樂感。",
        }
    if category == "簫":
        return {
            "lens": "慢氣、口風角度、長音和留白",
            "observation": "簫的問題通常出在氣太急、口風太散，令聲音沒有核心；單純吹大聲幫助不大。",
            "proof": "當學生能用小音量吹出穩定空音，古曲線條和句尾收束才會自然。",
        }
    return {
        "lens": "曲目、音階、視奏、聽覺和考場穩定度",
        "observation": "考級不是把三首曲吹熟就可以，真正會失分的位置常常在音階、視奏、伴奏入口和緊張後的第一句。",
        "proof": "當學生知道每星期要檢查哪一項，考級就不再只是倒數日期，而是一套能力整理。",
    }


