def trust_items(post: dict) -> list[tuple[str, str]]:
    reader = reader_group(post)
    kind = topic_kind(post)
    focus = plain_focus(post)
    base, _ = split_title(post)
    category = post["category"]
    labels = {
        "selection": (f"買{category}前想試清楚的人", f"暫時不宜急買{category}的人"),
        "breath": ("第一下聲音常散的人", "暫時不要只追音量的人"),
        "tone": ("想聽清楚音色分別的人", "暫時不要只靠換樂器的人"),
        "rhythm": ("拍子和手指常卡住的人", "暫時不要只練速度的人"),
        "pitch": ("音準經常飄的人", "暫時不要只盯調音器的人"),
        "exam": ("需要整理考級計劃的人", "暫時不宜只追分數的人"),
        "stage": ("準備上台或錄影的人", "暫時不要只通完整曲的人"),
        "care": ("樂器狀態開始有變的人", "暫時不要硬撐繼續用的人"),
        "child": ("家長想建立練習節奏的人", "暫時不要每堂只追新歌的人"),
        "adult": ("成人想用有限時間學習的人", "暫時不要等到很空才開始的人"),
        "recording": ("願意用錄音自查的人", "暫時不要一次改太多的人"),
        "ensemble": ("需要把合奏合得齊的人", "暫時不要只顧自己聲部的人"),
        "expression": ("想把句子吹得有語氣的人", "暫時不要只堆技巧的人"),
    }.get(kind, ("需要先找出源頭的人", "暫時不宜急着推進的人"))
    if kind == "selection":
        not_fit = f"如果只想即日買最熱門的{category}，不打算試手感和聽聲音，這種做法未必適合。"
    elif kind == "exam":
        not_fit = "如果只想追求保證分數，或希望短時間跳過基本功，這種準備方式未必適合。"
    elif kind == "child":
        not_fit = f"如果希望小朋友每堂都只學新歌，而不願意慢慢建立{focus}，這種安排未必適合。"
    else:
        not_fit = "如果只想由頭到尾多練幾次，不想拆基本功和練習習慣，這種學法未必適合。"
    fit_text = {
        "selection": f"{reader}，特別是還未試過實物、只靠網上評價或朋友推薦決定的人。",
        "breath": f"{reader}，特別是聲音一開始就散、硬、漏氣，卻不確定身體和嘴形怎樣配合的人。",
        "tone": f"{reader}，特別是已經吹得響，但分不清薄、散、硬和真正集中聲音的人。",
        "rhythm": f"{reader}，特別是一加速就亂、慢速也未能穩定重拍和分組的人。",
        "pitch": f"{reader}，特別是離開調音器後，耳朵仍找不到相鄰音距離的人。",
        "exam": f"{reader}，特別是曲目、音階、視奏和伴奏入口未排好先後的人。",
        "stage": f"{reader}，特別是平時練得可以，但一到錄影、彩排或表演第一句就不穩的人。",
        "care": f"{reader}，特別是最近聲音反應變慢、收拾習慣不穩，或不肯定是否要維修的人。",
        "child": f"{reader}，特別是孩子願意學，但家中練習容易變成催促和拉鋸的人。",
        "adult": f"{reader}，特別是工作日時間碎片化，想用短練習維持手感的人。",
        "recording": f"{reader}，特別是有錄音習慣，但聽完只覺得問題太多、不知先改哪裏的人。",
        "ensemble": f"{reader}，特別是自己聲部算熟，但一合伴奏或合奏就散的人。",
        "expression": f"{reader}，特別是音和拍子大致完成，但句子仍然平直、缺少呼吸的人。",
    }.get(kind, f"{reader}，特別是同一個問題在幾首曲都出現，卻分不清源頭的人。")
    return [
        (labels[0], fit_text),
        (labels[1], not_fit),
    ]


def article_meta_description(post: dict) -> str:
    category = post["category"]
    kind = topic_kind(post)
    tails = {
        "selection": f"張老師會按學生年齡、手感、用途和預算，整理買前要問的資料。",
        "breath": f"張老師會按{category}課堂常見情況，整理聽聲音、拆氣息和回家短練習。",
        "tone": f"張老師會用課堂常見例子，整理音頭、音中、收音和錄音回聽方法。",
        "rhythm": f"張老師會把拍點、分組和速度拆開，整理一星期可跟的練習方向。",
        "pitch": f"張老師會由相鄰音、耳朵和短句出發，整理較容易落地的檢查方法。",
        "exam": "張老師會把曲目、音階、視奏、聽覺和流程拆開，整理考前準備次序。",
        "stage": "張老師會把站位、呼吸、第一句和收結提前整理，減少臨場不穩。",
        "care": f"張老師會按香港天氣和日常使用情況，整理{category}保養與收納提醒。",
        "child": "張老師會從孩子能否跟到一個任務出發，整理家長陪練和查詢資料。",
        "adult": "張老師會按成人時間表、音量環境和目標，整理可持續的入門安排。",
        "recording": "張老師會把手機錄音變成簡單回聽流程，幫學生知道下一次先改哪裏。",
        "ensemble": "張老師會從入口、音量和角色分工出發，整理合奏前後要聽的位置。",
        "expression": "張老師會由唱句、留白和語氣出發，整理表達練習的先後次序。",
    }
    description = f"{post['excerpt']} {tails.get(kind, f'張老師會按{category}課堂情況，整理判斷步驟、短練習和查詢資料。')}"
    if len(description) < 80:
        description += f" 查詢前可先準備目前程度、可練時間和一段短{category}錄音，讓第一堂更快找到方向。"
    return description


