def premium_audience_faq(post: dict, detail: dict) -> tuple[str, str]:
    focus = plain_focus(post)
    base, _ = split_title(post)
    kind = topic_kind(post)
    category = post["category"]
    questions = {
        "selection": "誰最需要先問清楚？",
        "exam": "誰適合用這種方式整理考級進度？",
        "stage": "誰需要提前練舞台流程？",
        "child": "家長安排前要留意甚麼？",
        "adult": "成人學生要先想清楚甚麼？",
        "recording": "誰最適合用錄音處理？",
        "ensemble": "誰需要特別練合奏？",
        "care": "甚麼情況要特別留意？",
    }
    answers = {
        "selection": f"零基礎、兒童或未確定方向的學生最需要先問。熱門的{category}未必合用，仍要實際試手感和聽聲音反應。",
        "exam": "適合已經有曲目或考期，但弱項仍未排清楚的學生。把曲目、音階、視奏和聽覺分開，會實際得多。",
        "stage": f"準備表演、錄影或比賽的人都需要提前練。尤其是一上台就急、第一句不穩，或收結容易散的學生。",
        "child": f"家長最要留意孩子能否完成一個短任務。若每次回家都變成催促，通常要把{focus}拆得再細一點。",
        "adult": f"成人學生要先想清楚可用時間和練習環境。時間不多也可以學，但{focus}要拆成工作日也做得到的份量。",
        "recording": f"適合想自我檢查、但聽錄音時不知道先改哪裏的學生。先聽{focus}一項，比一次圈出十個問題更有用。",
        "ensemble": f"準備伴奏、二重奏或團體合奏的人都需要。只聽自己聲部時，{focus}很容易和整體脫節。",
        "care": f"剛買樂器、練習密度增加，或最近聲音和手感有變的人都要留意。香港濕度高，{focus}不能等到出事才處理。",
    }
    return (
        questions.get(kind, "誰應該先處理這個問題？"),
        answers.get(kind, f"適合正在學{category}，但仍聽不出{focus}哪一刻失手的學生。先把問題縮小，回家練習才有清楚方向。"),
    )


def premium_result_faq(post: dict) -> tuple[str, str]:
    kind = topic_kind(post)
    focus = plain_focus(post)
    base, _ = split_title(post)
    terms = instrument_terms(post)
    questions = {
        "exam": "能否保證分數？",
        "stage": "是否保證演出不出錯？",
        "selection": "選好後是否代表學得快？",
        "child": "小朋友會否很快見到成果？",
        "adult": "成人能否很快追上？",
        "care": "做好保養後是否就不會再有問題？",
    }
    if kind == "exam":
        answer = f"不能保證指定分數。張老師會做的是建立可檢查的準備流程，減少因{focus}不穩而失分。"
    elif kind == "stage":
        answer = f"不能保證現場完全沒有變數。可以做的是提前處理{focus}、第一句和流程，讓學生上台時有清楚依據。"
    elif kind == "selection":
        answer = "合用的樂器只是起點，之後仍要建立姿勢、聲音和練習習慣。張老師不會用型號或價錢保證進度。"
    elif kind == "care":
        answer = f"良好保養能減少風險，但不能保證永遠不需要調整。若{focus}突然變差，應盡早檢查。"
    elif kind == "child":
        answer = "小朋友的成果通常先表現在願意拿起樂器、能記得一個提醒、聲音或拍子比上星期穩。這比短時間學很多首歌更值得看。"
    elif kind == "adult":
        answer = f"成人進度要看可練時間和目標。先做到每星期有幾次短練習，{focus}自然比偶然一次長時間練習更容易累積。"
    elif kind == "recording":
        answer = f"通常幾次錄音後就會看到重複問題，例如{focus}、音頭或句尾。真正有用的是每次只改一項，下一次再比較。"
    elif kind == "ensemble":
        answer = f"一兩次合奏已能聽到入口和音量是否改善；至於{focus}是否穩，要看學生能否在別人聲音裏仍保持自己的位置。"
    else:
        answer = f"沒有固定時間。通常先看學生能否在{terms['unit']}裏穩定做到一次，再看隔幾天是否仍保持；這比承諾幾堂見效實際。"
    return (questions.get(kind, "多久會聽得出分別？"), answer)


def premium_cta(post: dict, copy: dict) -> tuple[str, str]:
    title, text = copy["cta"]
    return title, text


def premium_faq_pairs(post: dict, copy: dict, detail: dict) -> list[tuple[str, str]]:
    kind = topic_kind(post)
    focus = plain_focus(post)
    base, _ = split_title(post)
    faq1 = copy["faq1"]
    faq2 = copy["faq2"] if kind in {"selection", "local", "care"} else premium_self_study_faq(post)
    if kind == "selection":
        faq2 = ("買前是否要先問老師？", "如果是零基礎、兒童或未確定方向，先講清楚年齡、程度、預算和學習目標會較穩陣，老師也較容易按手型和聲音反應給方向。")
    if kind == "local":
        faq1 = ("一堂課應該包含甚麼？", f"應該有{focus}診斷、基本功、曲目應用和清楚的回家任務，而不是每堂只學新歌。")
        faq2 = ("查詢前要準備甚麼？", f"可以先準備目前程度、想學方向、可練習時間和一段短錄音，讓張老師更快判斷{focus}。")
    if kind == "care":
        faq1 = ("多久要做一次？", f"日常抹乾和收納每次練完都要做；如果聲音或手感突然變差，就應該盡早讓老師或維修師傅判斷。")
        faq2 = ("香港天氣下要注意甚麼？", "要避免水氣長時間留在樂器上，也不要放在冷氣直吹、窗邊或溫差太大的位置。")
    if kind == "exam":
        faq1 = ("幾時才算準備好？", "要看曲目、音階、視奏、聽覺和模擬流程是否穩定，不能只看其中一首曲能否吹完。")
        faq2 = ("是否只看分數？", "分數是結果之一，但張老師更重視考完後是否留下音準、節奏、聽覺和上台能力。")
    return [
        faq1,
        faq2,
        premium_lesson_faq(post, detail),
        premium_audience_faq(post, detail),
        premium_result_faq(post),
    ]


def method_line(post: dict) -> str:
    method = method_text(post)
    if method.startswith(("用", "以", "先", "至少", "把", "按", "從", "安排", "加入", "每次", "在")):
        return f"張老師會{method}"
    return f"張老師會先按學生情況判斷：{method}"


def topic_work_area(post: dict) -> str:
    kind = topic_kind(post)
    base, _ = split_title(post)
    focus = plain_focus(post)
    terms = instrument_terms(post)
    areas = {
        "selection": f"試吹、手感和{focus}裏看",
        "care": f"日常收拾和{focus}裏看",
        "local": f"第一堂課和{focus}裏看",
        "stage": f"彩排流程和{focus}裏看",
        "recording": f"錄音片段和{focus}裏聽",
        "child": f"孩子能否完成一個任務裏看",
        "adult": f"工作日可持續練習裏看",
        "exam": f"弱項表和{focus}裏看",
        "ensemble": f"合奏入口和{focus}裏聽",
    }
    return areas.get(kind, f"{terms['unit']}裏聽")


