def premium_context_paragraphs(post: dict, copy: dict, detail: dict) -> list[str]:
    kind = topic_kind(post)
    base, hook = split_title(post)
    focus = plain_focus(post)
    category = post["category"]
    pain = post["pain"]
    terms = instrument_terms(post)
    method = method_line(post)
    work_area = topic_work_area(post)
    method_note = method[4:] if method.startswith("張老師會") else method
    first_options = [
        f"{pain}，先不要急着把整段重練。課堂會找第一個走樣的位置，通常由那裏處理最快。",
        f"{pain}。回家若只把整段重練，問題很容易再次被藏起來；張老師會先圈出一個可重複檢查的位置。",
        f"這類問題要放到{work_area}。小位置一穩，後面才接得回去。",
    ]
    second_by_kind = {
        "selection": f"選樂器要同時看手感、聲音反應和用途。這些位置清楚了，價錢和型號才有比較意義。",
        "care": f"保養類問題要看習慣和樂器狀態：練完怎樣抹、放在哪裏、聲音反應有沒有變慢。",
        "child": f"兒童課堂要先看孩子能否聽明一個指令，再看家長回家能否用同一個提醒配合。",
        "adult": f"成人學生要把練習放回生活時間表。任務太大，即使有心也很難持續。",
        "exam": f"考級類問題要放進時間表。曲目、音階、視奏、聽覺和伴奏分開後，才知道哪一項最急。",
        "stage": f"舞台類問題要提前放進流程。站位、第一句、收音和結尾試過，學生才不會到現場才第一次面對。",
        "recording": f"錄音類問題要先定聆聽目標。固定距離、短片段和單一重點，比錄很長但不知聽甚麼更有用。",
        "ensemble": f"合奏類問題要聽整體；自己吹準只是起點，入口、音量和句尾常常比單音更早出問題。",
    }
    second_options = [
        f"課堂會檢查{detail['teacher_checks']}，再決定{method_note}應該放在哪一步做。",
        second_by_kind.get(kind, f"{category}課堂最怕把所有問題混在一起。先分清源頭，回家練習才有方向。"),
        f"張老師通常不會一開始通完整段，會先縮到{terms['unit']}。學生聽到問題後，才回到原來內容。",
    ]
    return [pick(first_options, post, 1), pick(second_options, post, 2)]


def premium_teacher_paragraphs(post: dict, detail: dict) -> list[str]:
    kind = topic_kind(post)
    base, _ = split_title(post)
    focus = plain_focus(post)
    category = post["category"]
    terms = instrument_terms(post)
    method = method_line(post)
    first_steps = {
        "selection": f"比較時，張老師會看學生拿起{post['category']}是否自然，再聽第一下聲音反應。",
        "breath": f"張老師會先聽{terms['start']}，再看肩膊有沒有升起、嘴形是否太緊，以及第一下聲音是否散開。",
        "tone": f"張老師會從{terms['start']}比較改動前後的分別，不只說一句好聽或不好聽。",
        "rhythm": f"張老師會把練習縮到{terms['unit']}，用慢速和分組檢查拍點，確定動作沒有搶前。",
        "pitch": f"張老師會從{terms['start']}放到相鄰音裏聽，看偏差是否每次都出現在同一個位置。",
        "expression": f"張老師會先用{terms['unit']}唱出句子，確認語氣後才加入技巧變化。",
        "exam": f"張老師會先看{focus}目前穩到哪裏，再分清曲目、音階、視奏和聽覺哪一項最急。",
        "stage": f"張老師會把{terms['unit']}、站位、第一句和收結拆開練，避免學生只靠臨場膽量。",
        "care": f"張老師會先看{category}的狀態，再分清收納習慣或日常使用是否造成問題。",
        "child": f"張老師會先看孩子能否用{category}完成一個清楚指令，再把課堂內容變成家中短任務。",
        "adult": f"張老師會先看學生平日可用時間，再把{category}練習拆成工作日也做得到的份量。",
        "recording": f"張老師會先聽{terms['start']}最明顯的一刻，避免學生一次聽太多問題。",
        "ensemble": f"張老師會先定{category}的主旋律、伴奏和入口位置，再聽各聲部是否互相配合。",
    }.get(kind, f"張老師會先聽{terms['start']}，再判斷最影響聲音的位置。")
    second_options = [
        f"{method}。學生要能說清楚{method[4:]}前後有甚麼分別，回家才知道應該重做哪一步。",
        f"課堂會把{focus}縮到一個音、一個手位或一小句；做到穩，再放回原來速度和樂句。",
        f"如果{terms['unit']}開始穩，就先停在那裏多做兩次，確定不是碰巧成功。",
    ]
    return [first_steps, pick(second_options, post, 3)]


