                ("伴奏要幾時開始夾？", "越早越好。至少要預留多次排練，讓速度、呼吸和入口有默契。"),
                ("張老師能否保證分數？", "不能保證指定分數。可以做的是建立可檢查的準備流程，減少臨場不穩。"),
