def svg_theme_cards(post: dict, accent: str, muted: str) -> str:
    cards = []
    for index, theme in enumerate(visual_themes(post)):
        x = 84 + index * 138
        y = 472 + (article_visual_seed(post) % 3) * 4
        cards.append(
            f"""
            <g transform="translate({x},{y})">
              <rect x="0" y="0" width="108" height="108" rx="18" fill="#ffffff" stroke="#ded8cf" stroke-width="2"/>
              {svg_theme_icon(theme, accent, muted)}
            </g>
            """
        )
    return "\n".join(cards)


def svg_context_panel(post: dict, accent: str, muted: str) -> str:
    seed = article_visual_seed(post)
    theme = visual_themes(post)[0]
    x = 96 + (seed % 3) * 18
    y = 310 + (seed % 4) * 10
    return f"""
      <g transform="translate({x},{y}) scale(1.18)">
        <rect x="0" y="0" width="126" height="126" rx="22" fill="#ffffff" stroke="#ded8cf" stroke-width="2" opacity=".94"/>
        <circle cx="100" cy="24" r="16" fill="{accent}" opacity=".12"/>
        {svg_theme_icon(theme, accent, muted)}
      </g>
    """


def svg_instrument(post: dict, accent: str, soft: str, dark: str) -> str:
    category = post["category"]
    seed = article_visual_seed(post)
    rotate = -10 + (seed % 7)
    if category == "長笛":
        keys = "".join(f'<circle cx="{150 + index * 55}" cy="0" r="{12 if index % 2 else 10}" fill="#ffffff" stroke="{dark}" stroke-width="4"/>' for index in range(7))
        return f"""
          <g transform="translate(365 340) rotate({rotate})">
            <rect x="-58" y="-14" width="642" height="28" rx="14" fill="#d7dde0" stroke="{dark}" stroke-width="5"/>
            <rect x="-18" y="-24" width="112" height="48" rx="20" fill="#f4f6f5" stroke="{dark}" stroke-width="4"/>
            <path d="M-84 -2 H-44" stroke="{dark}" stroke-width="6" stroke-linecap="round"/>
            {keys}
            <path d="M88 -44 C160 -94, 260 -88, 332 -48" fill="none" stroke="{accent}" stroke-width="7" stroke-linecap="round" opacity=".45"/>
          </g>
        """
    if category == "笛子":
        holes = "".join(f'<circle cx="{150 + index * 58}" cy="0" r="9" fill="#30271f" opacity=".82"/>' for index in range(6))
        bands = "".join(f'<rect x="{64 + index * 116}" y="-23" width="12" height="46" rx="3" fill="{dark}" opacity=".38"/>' for index in range(5))
        return f"""
          <g transform="translate(350 342) rotate({rotate})">
            <rect x="-30" y="-24" width="616" height="48" rx="24" fill="#caa873" stroke="{dark}" stroke-width="5"/>
            {bands}
            <circle cx="106" cy="0" r="24" fill="none" stroke="{accent}" stroke-width="8"/>
            {holes}
            <path d="M88 -50 C160 -78, 222 -76, 292 -46" fill="none" stroke="{accent}" stroke-width="7" stroke-linecap="round" opacity=".42"/>
          </g>
        """
    if category == "空靈鼓":
        tongues = "".join(f'<path d="M{520 + index * 36} {256 + (index % 3) * 34} C{546 + index * 28} {238 + (index % 3) * 24}, {574 + index * 20} {286 + (index % 2) * 32}, {538 + index * 30} {318 + (index % 3) * 22}" fill="none" stroke="#ffffff" stroke-width="9" stroke-linecap="round" opacity=".72"/>' for index in range(5))
        return f"""
          <g>
            <ellipse cx="626" cy="340" rx="268" ry="184" fill="{accent}" opacity=".92"/>
            <ellipse cx="626" cy="318" rx="248" ry="158" fill="{soft}" stroke="{dark}" stroke-width="7"/>
            {tongues}
            <path d="M392 510 L482 410" stroke="{dark}" stroke-width="12" stroke-linecap="round"/>
            <path d="M845 502 L768 405" stroke="{dark}" stroke-width="12" stroke-linecap="round"/>
            <circle cx="482" cy="410" r="20" fill="{accent}" opacity=".72"/>
            <circle cx="768" cy="405" r="20" fill="{accent}" opacity=".72"/>
            <circle cx="626" cy="318" r="210" fill="none" stroke="#ffffff" stroke-width="4" opacity=".34"/>
          </g>
        """
    if category == "簫":
        holes = "".join(f'<circle cx="0" cy="{118 + index * 52}" r="10" fill="#211b15" opacity=".8"/>' for index in range(6))
        return f"""
          <g transform="translate(620 112) rotate({4 - seed % 8})">
            <rect x="-24" y="0" width="48" height="456" rx="22" fill="#b99560" stroke="{dark}" stroke-width="5"/>
            <path d="M-26 68 H26 M-26 212 H26 M-26 356 H26" stroke="{accent}" stroke-width="8" opacity=".5"/>
            {holes}
            <path d="M-72 454 H72" stroke="{dark}" stroke-width="8" stroke-linecap="round"/>
          </g>
          <path d="M420 212 C488 152, 552 142, 612 166" fill="none" stroke="{accent}" stroke-width="7" stroke-linecap="round" opacity=".42"/>
        """
    staff = "".join(f'<path d="M500 {226 + index * 20} H820" stroke="{dark}" stroke-width="3" opacity=".45"/>' for index in range(5))
    checks = "".join(f'<path d="M548 {378 + index * 34} l14 14 l28 -30" fill="none" stroke="{accent}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>' for index in range(3))
    return f"""
      <g>
        <rect x="438" y="166" width="420" height="330" rx="22" fill="#ffffff" stroke="{dark}" stroke-width="6"/>
        <path d="M438 238 H858" stroke="{accent}" stroke-width="7" opacity=".5"/>
        {staff}
        <rect x="494" y="350" width="300" height="126" rx="16" fill="{soft}" opacity=".65"/>
        {checks}
        <path d="M732 164 L786 92 L842 164 Z" fill="{accent}" opacity=".78"/>
        <path d="M786 122 V178" stroke="#ffffff" stroke-width="6" stroke-linecap="round"/>
      </g>
    """


def article_svg(post: dict) -> str:
    profile = CATEGORIES[post["category"]]
    accent = profile["color"]
    soft = mix_color(accent, "#ffffff", 0.82)
    muted = mix_color(accent, "#ffffff", 0.58)
    dark = mix_color(accent, "#151515", 0.36)
    seed = article_visual_seed(post)
    window_x = 806 + (seed % 5) * 14
    alt = article_image_alt(post)
    bg_circles = "".join(
        f'<circle cx="{118 + index * 122}" cy="{96 + ((seed + index * 37) % 78)}" r="{10 + ((seed + index) % 16)}" fill="{accent}" opacity=".08"/>'
        for index in range(8)
    )
    staff_lines = "".join(f'<path d="M76 {184 + index * 18} H420" stroke="{dark}" stroke-width="3" opacity=".25"/>' for index in range(5))
    return f"""<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675" role="img" aria-labelledby="title desc">
  <title id="title">{e(alt)}</title>
  <desc id="desc">Semi-realistic editorial vector illustration for a Hong Kong music education article. No person, no face, no readable Chinese text inside the image.</desc>
  <defs>
    <linearGradient id="paper" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#fbfaf6"/>
      <stop offset=".55" stop-color="#f4efe6"/>
      <stop offset="1" stop-color="{soft}"/>
    </linearGradient>
  </defs>
  <rect width="1200" height="675" fill="url(#paper)"/>
  <rect x="58" y="58" width="1084" height="558" rx="34" fill="#ffffff" opacity=".58" stroke="#ded8cf" stroke-width="2"/>
  <rect x="{window_x}" y="82" width="242" height="176" rx="18" fill="#eef2ef" stroke="#d6d0c7" stroke-width="3"/>
  <path d="M{window_x + 121} 82 V258 M{window_x} 170 H{window_x + 242}" stroke="#d6d0c7" stroke-width="3"/>
  <path d="M64 438 H1138" stroke="#d8d0c5" stroke-width="4" opacity=".7"/>
  {bg_circles}
  <g opacity=".86">
    {staff_lines}
    <circle cx="132" cy="216" r="11" fill="{accent}" opacity=".45"/>
    <circle cx="206" cy="198" r="11" fill="{accent}" opacity=".55"/>
    <circle cx="286" cy="226" r="11" fill="{accent}" opacity=".42"/>
  </g>
  {svg_instrument(post, accent, soft, dark)}
  {svg_context_panel(post, accent, muted)}
  {svg_theme_cards(post, accent, muted)}
  <path d="M88 604 C262 556, 438 558, 598 604 S938 654, 1118 604" fill="none" stroke="{accent}" stroke-width="6" opacity=".16"/>
</svg>
"""


def article_html(post: dict, related: list[dict]) -> str:
    profile = CATEGORIES[post["category"]]
    scene = article_scene(post)
    method = method_text(post)
    visible_focus = plain_focus(post)
    base_title, _ = split_title(post)
    meta_description = article_meta_description(post)
    faq_heading = article_faq_heading(post)
    related_heading = article_related_heading(post)
    contact_heading = article_contact_heading(post, base_title)
    premium = premium_article(post)
    if premium:
        sections = premium["sections"]
        cta_title, cta_text = premium["cta"]
        faqs = premium["faqs"]
        summary_label = premium["summary_label"]
        summary_paragraphs = premium["summary"]
    else:
        sections = article_sections(post)
        cta_title, cta_text = cta_copy(post)
        faqs = article_faqs(post)
        summary_label = pick(["先講重點", "張老師的判斷", "讀者最要留意", "不用急着做的事"], post)
        summary_paragraphs = [
            scene,
            f"課堂中，張老師會{method}。這樣學生和家長才知道要先處理氣、手指、聽覺、節奏，還是練習方法。",
        ]
    faq_markup = "".join(
        f"""
        <details>
          <summary>{e(item['q'])}</summary>
          <p>{e(item['a'])}</p>
        </details>
        """
        for item in faqs
    )
    related_cards = "".join(
        f"""
        <a class="mini-card" href="../{p['url']}">
          <span>{e(p['category'])}</span>
          <strong>{e(p['title'])}</strong>
        </a>
        """
        for p in related
    )
    keyword_spans = "".join(f"<span>{e(k)}</span>" for k in post["keywords"][:8])
    side_links = "".join(f'<a href="#{e(section["id"])}">{e(section["nav"])}</a>' for section in sections)
    sections_html = "".join(render_article_section(section) for section in sections)
    summary_html = "".join(f"<p>{e(paragraph)}</p>" for paragraph in summary_paragraphs)
    contact_prep_html = "".join(
        f"<p>{e(paragraph)}</p>"
        for paragraph in article_contact_paragraphs(post, profile, base_title, visible_focus)
    )
    body = f"""
    <section class="article-hero">
      <div class="article-hero-inner">
        <nav class="breadcrumb" aria-label="文章位置">
          <a href="../index.html">首頁</a>
          <span>/</span>
          <a href="../blog.html">文章資料庫</a>
          <span>/</span>
          <span>{e(post['category'])}</span>
        </nav>
        <a class="back-link" href="../blog.html">← 返回文章資料庫</a>
        <p class="eyebrow">{e(post['category'])} · {e(post['level'])}</p>
        <h1>{e(post['title'])}</h1>
        <p class="article-lead">{e(post['excerpt'])}</p>
        <div class="article-meta">
          <span>{e(AUTHOR)}</span>
          <span>{e(post['date'])}</span>
          <span>{e(post['readTime'])}</span>
        </div>
      </div>
    </section>
    <section class="article-shell">
      <aside class="article-side">
        <p class="side-title">文章重點</p>
        <a href="#summary">先講結論</a>
        {side_links}
        <a href="#faq">{e(faq_heading)}</a>
        <div class="tag-cloud">{keyword_spans}</div>
      </aside>
      <article class="article-body" data-topic="{e(post['category'])}" data-primary-intent="{e(search_intent(post))}">
        <div class="answer-box" id="summary" aria-label="文章直接答案" data-ai-summary>
          <span>{e(summary_label)}</span>
          {summary_html}
        </div>

        {article_photo(post)}

        {sections_html}

        <h2 id="contact-prep">{e(contact_heading)}</h2>
        {contact_prep_html}

        {author_box(post)}

        <div class="soft-cta">
          <h2>{e(cta_title)}</h2>
          <p>{e(cta_text)}</p>
          <div class="hero-actions">
            <a class="btn primary" href="../contact.html"><span>↗</span>帶着問題查詢課程</a>
            <a class="btn" href="../blog.html"><span>⌕</span>繼續閱讀文章</a>
          </div>
        </div>

        <h2 id="faq">{e(faq_heading)}</h2>
        <div class="faq-list">{faq_markup}</div>
      </article>
    </section>
    <section class="band related-band">
      <div class="section-head">
        <p class="eyebrow">延伸閱讀</p>
        <h2>{e(related_heading)}</h2>
      </div>
      <div class="mini-grid">{related_cards}</div>
    </section>
    """
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            {
                "@type": "BlogPosting",
                "headline": post["title"],
                "description": meta_description,
                "abstract": " ".join(summary_paragraphs),
                "mainEntityOfPage": {"@type": "WebPage", "@id": absolute_url(post["url"])},
                "datePublished": post["date"],
                "dateModified": TODAY.isoformat(),
                "inLanguage": "zh-Hant",
                "author": {"@type": "Person", "@id": f"{BASE_URL}/about.html#teacher", "name": AUTHOR, "url": absolute_url("about.html"), "sameAs": SAME_AS},
                "publisher": {"@id": f"{BASE_URL}/#music-school"},
                "keywords": ", ".join(post["keywords"]),
                "articleSection": post["category"],
                "about": [post["category"], visible_focus, "香港音樂課程", "屯門音樂課程"],
                "mentions": post["keywords"][:8],
                "isAccessibleForFree": True,
                "image": [f"{BASE_URL}/{article_cover_path(post)}"],
                "url": f"{BASE_URL}/{post['url']}",
            },
            organization_schema(),
            {
                "@type": "FAQPage",
                "mainEntity": [
                    {
                        "@type": "Question",
                        "name": item["q"],
                        "acceptedAnswer": {"@type": "Answer", "text": item["a"]},
                    }
                    for item in faqs
                ],
            },
            {
                "@type": "BreadcrumbList",
                "itemListElement": [
                    {"@type": "ListItem", "position": 1, "name": "首頁", "item": absolute_url()},
                    {"@type": "ListItem", "position": 2, "name": "文章資料庫", "item": absolute_url("blog.html")},
                    {"@type": "ListItem", "position": 3, "name": post["category"], "item": absolute_url("blog.html")},
                    {"@type": "ListItem", "position": 4, "name": post["title"], "item": absolute_url(post["url"])},
                ],
            },
        ],
    }
    article_meta = "\n".join(
        [
            f'<meta property="article:published_time" content="{e(post["date"])}">',
            f'<meta property="article:modified_time" content="{e(TODAY.isoformat())}">',
            f'<meta property="article:section" content="{e(post["category"])}">',
        ]
        + [f'<meta property="article:tag" content="{e(keyword)}">' for keyword in post["keywords"][:6]]
    )
    return layout(
        title=post["title"],
        description=meta_description,
        body=body,
        active="blog",
        base="../",
        canonical_path=post["url"],
        og_type="article",
        og_image=article_cover_path(post),
        extra_head=article_meta + "\n" + json_ld(schema),
    )


