def courses_page() -> str:
    course_faqs = [
        ("完全零基礎應該先選哪一種課？", "先不用急着決定。可用課程建議器和成人頁整理需要，再由張老師按你提供的聲音喜好、手感和練習時間建議方向。"),
        ("課堂是否只適合考級學生？", "不是。考級只是其中一條路線，成人興趣、兒童啟蒙、合奏、舞台演出和放鬆音樂都可以有不同安排。"),
        ("第一堂會否直接學完整歌曲？", "視乎程度。零基礎通常先處理姿勢、發聲、節奏和短句，確保之後學曲不會一直卡在同一個基本問題。"),
        ("可以同時學兩種樂器嗎？", "可以，但初期要分清主次。張老師通常會先穩定一種樂器的基本聲音，再把共通能力轉移到第二種樂器。"),
    ]
    course_sections = []
    for name, profile in CATEGORIES.items():
        course_sections.append(
            f"""
            <article class="course-row" id="{profile['slug']}">
              <div>
                <p class="eyebrow">{e(name)}</p>
                <h2>{e(profile['tone'])}</h2>
                <p>{e(profile['promise'])}</p>
              </div>
              <ul class="check-list">
                <li>適合：零基礎、進階、成人興趣、考級或舞台演出。</li>
                <li>課堂：示範、診斷、短練習、曲目應用與回家任務。</li>
                <li>內容：{e(profile['practice'])}。</li>
                <li>搜尋定位：{e(profile['local'])}。</li>
              </ul>
            </article>
            """
        )
    body = f"""
    <section class="page-hero compact-hero">
      <p class="eyebrow">Courses</p>
      <h1>由入門到演奏，課程要有清楚路線。</h1>
      <p>新版把原有課程整理成五條學習路線，讓學生按樂器、程度和目標看清下一步。</p>
      <div class="hero-actions">
        <a class="btn primary" href="contact.html"><span>↗</span>課程查詢</a>
        <a class="btn ghost" href="adult-beginner.html"><span>◉</span>成人初學者入口</a>
      </div>
    </section>
    <section class="band advisor-band">
      <div class="split advisor-layout">
        <div>
          <h2>先整理目前程度和學習目標</h2>
          <p>選擇樂器與目標後，系統會顯示建議課程方向。正式課堂仍會由張老師根據聲音、姿勢和練習習慣重新評估。</p>
        </div>
        {advisor_markup()}
      </div>
    </section>
    <section class="band decision-band">
      <div class="section-head">
        <p class="eyebrow">Decision Guide</p>
        <h2>不是每個學生都應該用同一種上課方法。</h2>
        <p>正式課程前，先把「適合甚麼人」、「第一堂檢查甚麼」、「暫時未必適合甚麼」講清楚，訪客會更容易判斷。</p>
      </div>
      <div class="decision-grid">
        <div><span>適合</span><h3>想由基本功建立聲音的人</h3><p>長笛、笛子和簫都需要穩定氣息和聽覺；空靈鼓也需要拍子和句子，不是只憑感覺敲。</p></div>
        <div><span>第一堂</span><h3>先聽聲音，再定練習方向</h3><p>老師會看姿勢、手指、音色、拍子、練習時間和目標，再決定第一個月應該做甚麼。</p></div>
        <div><span>未必適合</span><h3>只想跳過基本功的人</h3><p>如果完全不想練聲音、節奏或手指，只想快些完成一首曲，進步很容易停在表面。</p></div>
      </div>
    </section>
    <section class="band">
      <div class="course-list">
        {''.join(course_sections)}
      </div>
    </section>
    <section class="band practice-band">
      <div class="split">
        <div>
          <p class="eyebrow">Practice Planner</p>
          <h2>本機練習清單</h2>
          <p>這是一個放在網站中的實用功能，學生可在自己電腦上勾選練習任務，瀏覽器會記住狀態。</p>
        </div>
        <div class="practice-planner" data-practice>
          <label><input type="checkbox"> 5分鐘長音 / 口風校準</label>
          <label><input type="checkbox"> 8分鐘音階或節奏分組</label>
          <label><input type="checkbox"> 10分鐘曲目難點慢練</label>
          <label><input type="checkbox"> 短錄音回聽</label>
          <label><input type="checkbox"> 寫下下次課堂要問的問題</label>
          <button class="btn small" type="button" data-reset-practice>重設</button>
        </div>
      </div>
    </section>
    {faq_section("選課前常見問題", "這些問題幫學生和家長先釐清期望，減少正式聯絡前的來回溝通。", course_faqs)}
    """
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            organization_schema(),
            {
                "@type": "ItemList",
                "name": "張老師音樂課程路線",
                "url": absolute_url("courses.html"),
                "itemListElement": [
                    {
                        "@type": "Course",
                        "position": index,
                        "name": f"{name}課程",
                        "description": profile["promise"],
                        "provider": {"@id": f"{BASE_URL}/#music-school"},
                    }
                    for index, (name, profile) in enumerate(CATEGORIES.items(), 1)
                ],
            },
            faq_schema(course_faqs),
        ],
    }
    return layout(
        title="課程",
        description="按學生程度、可練時間和目標整理不同樂器與考級路線，並列出基本功、適合對象、練習清單和查詢前要準備的資料，讓初學者、家長及考級學生更容易選定第一步。",
        body=body,
        active="courses",
        extra_head=json_ld(schema),
    )


def adult_beginner_page() -> str:
    adult_faqs = [
        ("成人學音樂最怕沒有時間，應該怎樣開始？", "先不要把練習想成一小時。每日5至10分鐘也可以處理長音、拍子、手感或錄音回聽，重點是目標要細。"),
        ("如果我不知道自己想學哪種樂器，可以先查詢嗎？", "可以。查詢時先講聲音喜好、家中音量、手感和目標，未必一開始就要買樂器。"),
        ("成人初學會否比小朋友慢？", "成人理解力通常較強，但身體放鬆和固定練習需要時間。方法合適時，進步可以很穩定。"),
        ("怕尷尬或怕吹不響怎樣辦？", "第一堂不應要求你表演，而是先找出最自然的發聲方式，再把問題拆細。"),
    ]
    read_urls = [
        "blog/flute-13-flute.html",
        "blog/dizi-14-dizi.html",
        "blog/tongue-drum-05-tongue-drum.html",
        "blog/xiao-01-xiao-xiao.html",
        "blog/exam-01-exam.html",
    ]
    read_notes = {
        "blog/flute-13-flute.html": "想學長笛但工作忙，可以先看怎樣把長音、呼吸和短句壓成可持續的練習。",
        "blog/dizi-14-dizi.html": "怕吹不響、怕尷尬的成人，先看笛子如何由口風和笛膜開始建立穩定聲音。",
        "blog/tongue-drum-05-tongue-drum.html": "如果你多數只能晚上或晚些練習，先看空靈鼓怎樣用小音量、留白和穩定節奏開始。",
        "blog/xiao-01-xiao-xiao.html": "如果你喜歡沉靜竹聲，先看簫的第一個音為何要慢慢找，再判斷是否適合長期練。",
        "blog/exam-01-exam.html": "如果你想把興趣變成清楚目標，先了解考級一年計劃需要哪些準備。",
    }
    post_map = {p["url"]: p for p in POSTS}
    first_reads = []
    for index, url in enumerate(read_urls, 1):
        post = post_map[url]
        first_reads.append(
            f"""
            <a class="route-card" href="{e(post['url'])}">
              <span class="step">{index:02d}</span>
              <small>{e(post['category'])}</small>
              <strong>{e(post['title'])}</strong>
              <p>{e(read_notes[url])}</p>
            </a>
            """
        )
    schema = {
        "@context": "https://schema.org",
        "@type": "WebPage",
        "name": "成人初學者音樂課程入口",
        "description": "張老師音樂學院成人初學者路線，協助香港成人在長笛、笛子、簫、空靈鼓及考級方向之間整理學習需要。",
        "about": ["成人音樂課程", "長笛", "笛子", "簫", "空靈鼓", "音樂考級"],
        "author": {"@id": f"{BASE_URL}/about.html#teacher"},
        "isPartOf": {"@type": "WebSite", "name": SITE_NAME, "url": BASE_URL},
    }
    body = f"""
    <section class="page-hero compact-hero adult-hero">
      <p class="eyebrow">Adult Beginner Path</p>
      <h1>成人初學者，由這裏開始。</h1>
      <p>不用一開始就逼自己決定學哪一種樂器。先聽自己喜歡的聲音，再看住家音量、練習時間和目標，張老師會把長笛、笛子、簫、空靈鼓和考級方向講清楚。</p>
      <div class="hero-actions">
        <a class="btn primary" href="#assessment"><span>⌕</span>整理查詢資料</a>
        <a class="btn ghost" href="#first-reads"><span>↓</span>先讀5篇文章</a>
        <a class="btn ghost" href="contact.html"><span>↗</span>課程查詢</a>
      </div>
    </section>

    <section class="quick-stats adult-stats">
      <div><strong>4</strong><span>種成人入門方向</span></div>
      <div><strong>5</strong><span>篇先讀文章</span></div>
      <div><strong>短</strong><span>練習也能開始</span></div>
      <div><strong>1</strong><span>份查詢前整理</span></div>
    </section>

    <section class="band" id="first-reads">
      <div class="section-head">
        <p class="eyebrow">Start Reading</p>
        <h2>如果你是成人零基礎，先讀這5篇。</h2>
        <p>這5篇會先幫你排除最常見的猶豫：怕吹不響、怕沒有時間、怕聲音太大、怕學了才發現不適合，而不是把所有知識一次塞滿。</p>
      </div>
      <div class="article-ladder">
        {''.join(first_reads)}
      </div>
    </section>

    <section class="band">
      <div class="section-head">
        <p class="eyebrow">Instrument Choice</p>
        <h2>四種樂器，適合的成人狀態不同。</h2>
      </div>
      <div class="answer-grid instrument-picker">
        <div class="answer-box" style="--accent:#0f6b68"><span>長笛</span><p>適合喜歡明亮、乾淨、西樂線條的人。需要每日短時間處理口型、呼吸和長音，之後可走考級、古典曲目和合奏方向。</p></div>
        <div class="answer-box" style="--accent:#7a2430"><span>笛子</span><p>適合喜歡竹聲、民樂語氣和直接音色的人。入門要面對笛膜、口風和筒音概念，聲音有辨識度，也適合舞台和中樂合奏。</p></div>
        <div class="answer-box" style="--accent:#3f6f4f"><span>簫</span><p>適合想慢下來、喜歡沉靜竹聲的人。簫不靠速度取勝，重點是長音、氣息和句子留白；深夜練習仍要留意氣聲穿透和住家環境。</p></div>
        <div class="answer-box" style="--accent:#5b4b8a"><span>空靈鼓</span><p>適合想較快聽到完整聲音、重視放鬆和節奏手感的人。若多數只能晚些練習，空靈鼓較容易用輕觸、小音量和短循環控制聲量。</p></div>
      </div>
    </section>

    <section class="band assessment-band" id="assessment">
      <div class="split assessment-layout">
        <div>
          <p class="eyebrow">Before Enquiry</p>
          <h2>查詢前，先把自己的聲音喜好、時間和目標整理好。</h2>
          <p>下面幾個選項不是正式評估，只是幫你在聯絡前講清楚自己的情況。張老師會按你的背景、目標和可練時間，再建議第一堂課應該從哪裏開始。</p>
          <ul class="check-list">
            <li>你喜歡哪一種聲音。</li>
            <li>你一星期能練多少次。</li>
            <li>你想興趣、考級、演出，還是放鬆。</li>
            <li>你最擔心吹不響、怕嘈、怕尷尬，還是怕沒有時間。</li>
          </ul>
        </div>
        <form class="adult-assessment" data-adult-assessment>
          <div class="choice-group">
            <p>你最想要哪一種聲音？</p>
            <div class="choice-grid">
              <label class="choice-card"><input type="radio" name="sound" value="bright" checked><span>明亮、有舞台感</span><small>長笛方向較接近</small></label>
              <label class="choice-card"><input type="radio" name="sound" value="folk"><span>竹聲、有民樂味</span><small>笛子方向較接近</small></label>
              <label class="choice-card"><input type="radio" name="sound" value="calm"><span>沉靜、慢慢呼吸</span><small>簫方向較接近</small></label>
              <label class="choice-card"><input type="radio" name="sound" value="relax"><span>放鬆、有共鳴</span><small>空靈鼓方向較接近</small></label>
            </div>
          </div>
          <div class="choice-group">
            <p>你的練習時間較像哪一種？</p>
            <div class="choice-grid">
              <label class="choice-card"><input type="radio" name="time" value="short" checked><span>每日5至10分鐘</span><small>要短、清楚、容易開始</small></label>
              <label class="choice-card"><input type="radio" name="time" value="steady"><span>每日15至20分鐘</span><small>可以建立基本功</small></label>
              <label class="choice-card"><input type="radio" name="time" value="weekend"><span>週末較完整</span><small>適合課堂後集中整理</small></label>
              <label class="choice-card"><input type="radio" name="time" value="unknown"><span>暫時不穩定</span><small>先找最容易持續的方法</small></label>
            </div>
          </div>
          <div class="choice-group">
            <p>你最主要的目標是甚麼？</p>
            <div class="choice-grid">
              <label class="choice-card"><input type="radio" name="goal" value="hobby" checked><span>純興趣</span><small>想有一個穩定愛好</small></label>
              <label class="choice-card"><input type="radio" name="goal" value="exam"><span>可能想考級</span><small>需要時間表和基本功</small></label>
              <label class="choice-card"><input type="radio" name="goal" value="stage"><span>想演奏給人聽</span><small>需要曲目和表達</small></label>
              <label class="choice-card"><input type="radio" name="goal" value="relax"><span>放鬆減壓</span><small>重視聲音和情緒</small></label>
            </div>
          </div>
          <div class="choice-group">
            <p>你對音量最介意的是甚麼？</p>
            <div class="choice-grid">
              <label class="choice-card"><input type="radio" name="volume" value="quiet" checked><span>晚上要安靜</span><small>較適合先看空靈鼓小音量練習</small></label>
              <label class="choice-card"><input type="radio" name="volume" value="normal"><span>可正常練習</span><small>可接受日間聲量</small></label>
            </div>
          </div>
          <div class="assessment-result" data-adult-result role="status" aria-live="polite"></div>
          <button class="btn small" type="button" data-reset-adult>重設選項</button>
        </form>
      </div>
    </section>

    <section class="band dark-band">
      <div class="section-head">
        <p class="eyebrow">First Month</p>
        <h2>成人第一個月，不應只追求「學到幾多首歌」。</h2>
      </div>
      <div class="lesson-roadmap">
        <div><span>第一堂</span><strong>找聲音</strong><p>先看姿勢、呼吸、手感和最自然的反應。</p></div>
        <div><span>第二堂</span><strong>定短練習</strong><p>把每天可做到的內容壓細，避免一開始太重。</p></div>
        <div><span>第三堂</span><strong>接入小曲</strong><p>用短句或簡單音型，把基本功放回音樂裏。</p></div>
        <div><span>第四堂</span><strong>檢查路線</strong><p>再決定繼續興趣、考級、合奏或轉另一種樂器。</p></div>
      </div>
    </section>

    <section class="band">
      <div class="split">
        <div>
          <p class="eyebrow">Enquiry Note</p>
          <h2>查詢時，直接帶這4點給張老師。</h2>
        </div>
        <ul class="check-list enquiry-list">
          <li>你是成人零基礎，還是曾經學過其他樂器。</li>
          <li>你較喜歡長笛、笛子、簫、空靈鼓，或仍未決定。</li>
          <li>你平日大概可練習多少時間，家中音量是否有限制。</li>
          <li>你最想解決的問題：吹不響、怕尷尬、想考級、想放鬆，還是想有舞台目標。</li>
        </ul>
      </div>
      <div class="hero-actions final-actions">
        <a class="btn primary" href="contact.html"><span>↗</span>整理資料後查詢課程</a>
        <a class="btn" href="blog.html"><span>⌕</span>返回文章資料庫</a>
      </div>
    </section>
    {faq_section("成人初學者最常問的問題", "這些答案先把成人學習最現實的阻力講清楚，不是催促你報名。", adult_faqs)}
    """
    return layout(
        title="成人初學者入口",
        description="香港成人初學者音樂課程入口，幫你在長笛、笛子、簫、空靈鼓和考級方向之間整理聲音喜好、練習時間、音量限制、學習目標和查詢資料，也說明工作日短練習可以怎樣開始和延續。",
        body=body,
        active="adult",
        extra_head=json_ld({"@context": "https://schema.org", "@graph": [organization_schema(), schema, faq_schema(adult_faqs)]}),
    )


def blog_page() -> str:
    counts = {cat: sum(1 for post in POSTS if post["category"] == cat) for cat in CATEGORIES}
    buttons = f'<button type="button" class="active" data-filter="全部">全部 <span>{len(POSTS)}</span></button>' + "".join(
        f'<button type="button" data-filter="{e(cat)}">{e(cat)} <span>{counts[cat]}</span></button>' for cat in CATEGORIES
    )
    stat_tiles = "".join(
        f'<div style="--accent:{CATEGORIES[cat]["color"]}"><strong>{counts[cat]}</strong><span>{e(cat)}文章</span></div>'
        for cat in CATEGORIES
    )
    post_map = {post["url"]: post for post in POSTS}
    route_entries = [
        ("長笛入門路線", "先看選購、口型和長音，適合想建立清亮音色的學生。", "blog/flute-01-flute.html"),
        ("笛子入門路線", "由笛膜、口風和筒音概念開始，避免只追求吹響。", "blog/dizi-01-dizi.html"),
        ("空靈鼓放鬆路線", "先建立拍點和左右手，再加入即興和合奏想法。", "blog/tongue-drum-01-tongue-drum.html"),
        ("簫慢練路線", "由第一個空音、長音和氣息留白開始，適合喜歡沉靜竹聲和慢練節奏的人。", "blog/xiao-01-xiao-xiao.html"),
        ("考級準備路線", "先看一年計劃，再分開處理音階、視奏、聽覺和伴奏。", "blog/exam-01-exam.html"),
    ]
    route_cards = "".join(
        f"""
        <a class="route-card library-route-card" href="{e(post_map[url]['url'])}">
          <span class="step">{index:02d}</span>
          <small>{e(post_map[url]['category'])}</small>
          <strong>{e(title)}</strong>
          <p>{e(text)}</p>
        </a>
        """
        for index, (title, text, url) in enumerate(route_entries, 1)
    )
    blog_faqs = [
        ("100篇文章應該怎樣讀？", "不要由第一篇讀到最後一篇。先按樂器或目標篩選，再選一條閱讀路線，遇到課堂問題時回來查相關文章。"),
        ("文章標題很多，怎樣知道哪篇最適合我？", "可以用搜尋欄輸入口型、音色、笛膜、考級、成人等關鍵字，也可以先看上方五條閱讀路線。"),
        ("文章內容會否重複？", "每篇文章圍繞不同課堂情境和練習重點，並用分類、關鍵字和延伸閱讀連接，而不是用同一套模板複製。"),
        ("我看完文章後下一步應該做甚麼？", "把最貼近自己的問題記下，查詢時直接告訴張老師，最好再附上一段短錄音。"),
    ]
    body = f"""
    <section class="page-hero compact-hero">
      <p class="eyebrow">Blog Library</p>
      <h1>100篇張老師音樂學習文章。</h1>
      <p>每個主題20篇：長笛、笛子、空靈鼓、簫、考級。文章以學生和家長真正會遇到的問題出發，整理入門、練習、考級和選課方向。</p>
    </section>
    <section class="library-stats" aria-label="文章分類統計">
      {stat_tiles}
    </section>
    <section class="band blog-route-band">
      <div class="route-banner">
        <div>
          <p class="eyebrow">For Adult Beginners</p>
          <h2>成人初學者不知道先讀哪篇？</h2>
          <p>先到成人入口頁，用聲音、時間、目標和住家環境找出較合適的文章路線。</p>
        </div>
        <a class="btn primary" href="adult-beginner.html"><span>◉</span>成人初學者入口</a>
      </div>
    </section>
    <section class="band library-route-band">
      <div class="section-head">
        <p class="eyebrow">Reading Routes</p>
        <h2>先選一條路線，不用一次看完100篇。</h2>
        <p>這些路線按真實查詢情境整理，讓新訪客不用在100篇文章之間迷路。</p>
      </div>
      <div class="article-ladder">
        {route_cards}
      </div>
    </section>
    <section class="band blog-tools">
      <div class="search-panel">
        <label for="blogSearch">搜尋文章</label>
        <input id="blogSearch" type="search" placeholder="輸入：長笛音色、笛膜、考級、空靈鼓...">
        <button class="btn small" type="button" data-clear-blog-search>清除搜尋</button>
      </div>
      <div class="sort-panel">
        <label for="blogSort">排序</label>
        <select id="blogSort" data-blog-sort>
          <option value="recommended">建議閱讀次序</option>
          <option value="latest">最新發布</option>
          <option value="category">按樂器分類</option>
        </select>
      </div>
      <div class="filter-tabs" data-blog-filters>{buttons}</div>
      <p class="blog-count" data-blog-count role="status" aria-live="polite"></p>
    </section>
    <section class="band">
      <div class="blog-grid" data-blog-list></div>
      <p class="empty-state" data-empty role="status" hidden>找不到文章，請換一個關鍵字。</p>
    </section>
    {faq_section("文章資料庫常見問題", "這一區幫讀者更快使用100篇內容，也讓搜尋引擎看得懂網站結構。", blog_faqs)}
    """
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            organization_schema(),
            {
                "@type": "CollectionPage",
                "name": "張老師音樂學習文章資料庫",
                "description": "100篇長笛、笛子、空靈鼓、簫與音樂考級文章。",
                "url": absolute_url("blog.html"),
                "isPartOf": {"@type": "WebSite", "name": SITE_NAME, "url": BASE_URL},
                "about": list(CATEGORIES.keys()),
                "mainEntity": {
                    "@type": "ItemList",
                    "numberOfItems": len(POSTS),
                    "itemListElement": [
                        {"@type": "ListItem", "position": index, "url": absolute_url(post["url"]), "name": post["title"]}
                        for index, post in enumerate(POSTS, 1)
                    ],
                },
            },
            faq_schema(blog_faqs),
        ],
    }
    return layout(
        title="文章資料庫",
        description="這裏整理100篇實用音樂學習內容，由選樂器、基本功、日常練習到考級和演出準備均有清楚分類，方便家長、成人初學者和學生按目前遇到的問題找到合適閱讀方向。",
        body=body,
        active="blog",
        extra_head=json_ld(schema),
        scripts='<script src="assets/js/blog-index.js"></script>',
    )


def hub_page() -> str:
    guide_faqs = [
        ("香港成人初學長笛會否太遲？", "不會。成人學長笛要先把呼吸、口型和練習時間拆細，不需要和小朋友或考級學生比較。每日短練習比偶然一次長練習更穩。"),
        ("屯門或新界西上課前要準備甚麼？", "先整理想學的樂器、目前程度、可上堂時間、家中練習音量和目標。如果已經學過，帶一段短錄音會更容易判斷方向。"),
        ("晚上練習哪種樂器較容易控制聲量？", "如果只能晚些練習，空靈鼓較容易用輕觸、小音量和短循環開始；簫雖然沉靜，但氣聲仍可能穿透，需要看住家環境。"),
        ("小朋友初學是否應該先以考級為目標？", "不一定。考級可以是階段目標，但初期更重要是專注時間、手型、聲音穩定和回家練習節奏。"),
        ("買第一支長笛或笛子前應先問甚麼？", "先問學生身高、手感、聲音反應、預算、保養和學習目標，而不是只看品牌、價錢或網上評價。"),
        ("空靈鼓是否只適合放鬆？", "不是。空靈鼓可以由放鬆入門，但要學好仍然要拍點、左右手、低音支點、句子和簡單合奏概念。"),
        ("簫和笛子應該如何選？", "笛子較明亮，入門成功感通常較快；簫較沉靜，需要更細的氣息和耐性。選擇要看音色喜好、練習環境和長期目標。"),
        ("考級前多久開始準備較穩？", "要看級別和程度。一般不應只在考前通曲，應提早安排音階、視奏、聽覺、伴奏和模擬考，讓弱項有時間修正。"),
    ]
    guide_details = faq_items(guide_faqs, open_first=True)
    topic_routes = [
        ("香港長笛課程", "適合想了解長笛入門、口型、音色、選笛與考級路線的學生。", "courses.html", "長笛"),
        ("成人初學音樂", "先整理聲音喜好、住家音量、工作日練習時間和第一堂要問的問題。", "adult-beginner.html", "成人"),
        ("笛子、簫與中樂吹管", "比較笛子、竹笛、洞簫和簫的聲音、吹法、手感與長期練習節奏。", "blog/dizi-17-dizi-xiao.html", "吹管"),
        ("空靈鼓與放鬆音樂", "由拍點、左右手、調式、留白和簡單合奏理解空靈鼓，不只停留在隨意敲。", "blog/tongue-drum-01-tongue-drum.html", "空靈鼓"),
        ("音樂考級規劃", "把曲目、音階、視奏、聽覺、伴奏和模擬考拆成可執行的季度任務。", "blog/exam-01-exam.html", "考級"),
    ]
    topic_route_cards = "".join(
        f"""
        <a class="mini-card" href="{e(url)}">
          <span>{e(label)}</span>
          <strong>{e(title)}</strong>
          <p>{e(text)}</p>
        </a>
        """
        for title, text, url, label in topic_routes
    )
    body = f"""
    <section class="page-hero compact-hero">
      <p class="eyebrow">Learning Guide</p>
      <h1>學長笛、笛子、簫和空靈鼓前，可以先了解這些問題。</h1>
      <p>這一頁把課程、地區、樂器和常見問題集中整理，方便學生和家長先了解可以由哪裏開始。</p>
      <div class="hero-actions">
        <a class="btn primary" href="contact.html"><span>↗</span>課程查詢</a>
        <a class="btn ghost" href="blog.html"><span>⌕</span>瀏覽100篇文章</a>
      </div>
    </section>
    <section class="band">
      <div class="answer-grid">
        <div class="answer-box"><span>張老師是誰？</span><p>張老師 Oliver Cheung 是以長笛與中樂吹管教學為核心的香港音樂老師，提供長笛、笛子、簫、空靈鼓及考級相關課程。</p></div>
        <div class="answer-box"><span>可以學甚麼？</span><p>學生可按目標選擇音色基礎、曲目訓練、考級規劃、成人興趣、親子活動或舞台演出準備。</p></div>
        <div class="answer-box"><span>地區定位</span><p>網站內容聚焦香港、屯門西鐵站一帶、新界西及可延伸的網上音樂學習查詢。</p></div>
      </div>
    </section>
    <section class="band">
      <div class="section-head">
        <p class="eyebrow">Course Map</p>
        <h2>張老師課程可以怎樣分類？</h2>
      </div>
      <div class="entity-grid">
        <div><h3>人物</h3><p>張老師、Oliver Cheung、長笛老師、笛子老師、考級導師。</p></div>
        <div><h3>樂器</h3><p>長笛、笛子、竹笛、簫、洞簫、空靈鼓、音舌鼓。</p></div>
        <div><h3>課程</h3><p>一對一課程、成人課程、兒童啟蒙、考級準備、演出訓練、工作坊。</p></div>
        <div><h3>地區</h3><p>香港、屯門、屯門西鐵站、新界西、網上音樂課。</p></div>
      </div>
    </section>
    <section class="band">
      <div class="section-head">
        <p class="eyebrow">Topic Authority</p>
        <h2>搜尋和 AI 最應該理解的五個主題入口</h2>
        <p>這些入口把課程頁、成人入口和代表文章串起來，讓搜尋引擎與 AI 模型更容易判斷網站專長，而不是只看到零散文章。</p>
      </div>
      <div class="mini-grid">{topic_route_cards}</div>
    </section>
    <section class="band dark-band">
      <div class="section-head">
        <p class="eyebrow">Questions</p>
        <h2>家長和學生常問的問題</h2>
      </div>
      <div class="faq-list wide">
        {guide_details}
      </div>
    </section>
    """
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            organization_schema(),
            {
                "@type": "WebPage",
                "name": "學習指南中心",
                "description": "張老師音樂學院學習指南，集中回答香港學生和家長在長笛、笛子、簫、空靈鼓與考級課程前常見的選擇問題。",
                "url": absolute_url("ai-seo-hub.html"),
                "isPartOf": {"@type": "WebSite", "name": SITE_NAME, "url": BASE_URL},
                "about": ["長笛", "笛子", "簫", "空靈鼓", "音樂考級", "香港音樂課程", "屯門音樂課程"],
            },
            faq_schema(guide_faqs),
        ],
    }
    return layout(
        title="學習指南中心",
        description="香港學生和家長在選樂器、安排課堂及準備考級前，往往有不少實際問題。這裏按程度、可練時間和學習目標整理閱讀入口、常見答案及查詢前要準備的資料。",
        body=body,
        active="hub",
        extra_head=json_ld(schema),
    )


def contact_page() -> str:
    contact_faqs = [
        ("本機版填寫的內容會送出去嗎？", "不會。本頁只是幫你整理查詢訊息，內容不會被網站儲存或提交到後台。"),
        ("生成訊息後應該怎樣聯絡？", "你可以複製整理好的訊息，再前往原有 Oliver Flute 網站使用正式聯絡方式。"),
        ("查詢時要不要先買樂器？", "零基礎學生不一定要先買。可以先說明想學的方向，讓張老師按情況給課程或選購建議。"),
        ("短錄音有甚麼幫助？", "如果你已經學過一段時間，一段最近練習錄音可以讓老師更快判斷音色、節奏或手指問題。"),
    ]
    body = f"""
    <section class="page-hero compact-hero">
      <p class="eyebrow">Enquiry</p>
      <h1>先整理目標，再聯絡張老師。</h1>
      <p>本機版不連接後台；這裡提供查詢訊息產生器，方便學生或家長把學習背景說清楚。</p>
    </section>
    <section class="band">
      <div class="split">
        <div>
          <h2>查詢前可先準備三件事</h2>
          <ul class="check-list">
            <li>想學的樂器與目前程度。</li>
            <li>是否有考級、演出、成人興趣或親子活動目標。</li>
            <li>每週可練習的實際時間。</li>
          </ul>
          <p>本機版不儲存任何表單資料。你可以先在這裏整理訊息，再前往原站用正式方式聯絡張老師。</p>
          <a class="btn primary" href="https://www.oliverflute.com/" target="_blank" rel="noopener"><span>↗</span>前往原站聯絡</a>
        </div>
        <form class="contact-builder" data-contact-builder>
          <label>姓名
            <input name="name" type="text" placeholder="例如：陳太 / Alex" autocomplete="name">
          </label>
          <label>樂器
            <select name="instrument" autocomplete="off">
              <option>長笛</option><option>笛子</option><option>空靈鼓</option><option>簫</option><option>考級</option>
            </select>
          </label>
          <label>程度
            <input name="level" type="text" placeholder="例如：零基礎 / 已學兩年 / 準備五級" autocomplete="off">
          </label>
          <label>目標
            <textarea name="goal" rows="4" placeholder="例如：希望改善音色，半年後考級。" autocomplete="off"></textarea>
          </label>
          <div class="form-actions">
            <button class="btn" type="button" data-build-message>生成查詢訊息</button>
            <button class="btn small" type="button" data-copy-message>複製訊息</button>
          </div>
          <textarea class="message-output" rows="6" data-message-output readonly></textarea>
          <p class="form-note" data-copy-status aria-live="polite">這裏只生成文字，不會提交資料。</p>
        </form>
      </div>
    </section>
    <section class="band privacy-band">
      <div class="answer-grid">
        <div class="answer-box"><span>不儲存資料</span><p>本機版表單只在你的瀏覽器內生成文字，不會提交到伺服器。</p></div>
        <div class="answer-box"><span>先整理再聯絡</span><p>把程度、目標、可練時間寫清楚，老師較容易判斷第一堂方向。</p></div>
        <div class="answer-box"><span>避免空泛查詢</span><p>比起只問「幾錢」或「有沒有位」，先講學習背景會更有效率。</p></div>
      </div>
    </section>
    {faq_section("課程查詢常見問題", "這些問題把本機版限制、查詢方式和聯絡前準備講清楚，避免訪客誤解。", contact_faqs)}
    """
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            organization_schema(),
            {
                "@type": "ContactPage",
                "name": "課程查詢",
                "description": "張老師音樂學院課程查詢與聯絡準備頁。",
                "url": absolute_url("contact.html"),
                "isPartOf": {"@type": "WebSite", "name": SITE_NAME, "url": BASE_URL},
                "about": {"@id": f"{BASE_URL}/#music-school"},
            },
            faq_schema(contact_faqs),
        ],
    }
    return layout(
        title="課程查詢",
        description="查詢前可先整理目前程度、學習目標、每星期可練時間、上堂地區和最近遇到的問題；資料愈清楚，老師愈容易判斷第一堂應由哪裏開始，以及要先聽哪一段。",
        body=body,
        active="contact",
        extra_head=json_ld(schema),
    )


def not_found_page() -> str:
    body = """
    <section class="page-hero compact-hero">
      <p class="eyebrow">404</p>
      <h1>找不到這個頁面。</h1>
      <p>可能是文章連結已更改，或你輸入的網址有誤。可以回到文章資料庫，或先從成人初學者入口開始整理學習方向。</p>
      <div class="hero-actions">
        <a class="btn primary" href="blog.html"><span>⌕</span>返回文章資料庫</a>
        <a class="btn ghost" href="adult-beginner.html"><span>◉</span>成人初學者入口</a>
        <a class="btn ghost" href="contact.html"><span>↗</span>課程查詢</a>
      </div>
    </section>
    """
    return layout(
        title="找不到頁面",
        description="原來的連結可能已經更新。你可以返回首頁、閱讀分類、成人初學者入口、課程或查詢位置，繼續按目前程度、可練時間和學習目標尋找合適的音樂內容。",
        body=body,
        active="home",
        canonical_path="404.html",
        robots_content="noindex,follow",
    )


def css() -> str:
    return r"""
:root {
  --ink: #1d2824;
  --sumi: #111816;
  --muted: #65716b;
  --paper: #f7f8f4;
  --panel: #fffffb;
  --wash: #edf4f1;
  --line: #d9ded5;
  --gold: #846620;
  --teal: #2e756e;
  --burgundy: #8a4d57;
  --plum: #63718c;
  --moss: #617f66;
  --serif: "Noto Serif TC", "Songti TC", "PMingLiU", serif;
  --sans: "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", sans-serif;
  --shadow: 0 18px 46px rgba(29, 40, 36, 0.09);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--sans);
  color: var(--ink);
  background: var(--paper);
  line-height: 1.75;
  letter-spacing: 0;
}
a { color: inherit; }
img { max-width: 100%; display: block; }
button, input, select, textarea {
  font: inherit;
}
.skip-link {
  position: absolute;
  left: 12px;
  top: -80px;
  background: var(--ink);
  color: white;
  padding: 8px 12px;
  z-index: 100;
}
.skip-link:focus { top: 12px; }
.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 13px 38px;
  background: rgba(247, 248, 244, 0.92);
  border-bottom: 1px solid rgba(29, 40, 36, 0.08);
  backdrop-filter: blur(16px);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  min-width: 220px;
}
.brand img {
  width: 40px;
  height: 40px;
  object-fit: contain;
  border-radius: 6px;
}
.brand strong {
  display: block;
  font-size: 1rem;
  line-height: 1.2;
  font-family: var(--serif);
  letter-spacing: 0;
}
.brand small {
  display: block;
  font-size: .72rem;
  color: var(--muted);
  font-family: var(--sans);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.main-nav a {
  text-decoration: none;
  padding: 8px 13px;
  border-radius: 8px;
  font-size: .92rem;
  color: #2d3632;
}
.main-nav a.active,
.main-nav a:hover {
  background: var(--ink);
  color: white;
}
.header-cta {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 8px 13px;
  border-radius: 8px;
  background: #b99748;
  color: #17140d;
  font-weight: 700;
  text-decoration: none;
  box-shadow: 0 8px 18px rgba(29, 40, 36, .08);
}
.nav-toggle {
  display: none;
  width: 42px;
  height: 42px;
  border: 1px solid var(--line);
  background: var(--panel);
  border-radius: 8px;
  color: var(--ink);
}
.hero {
  position: relative;
  min-height: 520px;
  height: 62vh;
  max-height: 640px;
  display: flex;
  align-items: center;
  background-image: image-set(url("../images/concert-studio-hero.webp") type("image/webp"), url("../images/concert-studio-hero.png") type("image/png"));
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  overflow: hidden;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(17, 24, 22, .74) 0%, rgba(17, 24, 22, .48) 38%, rgba(17, 24, 22, .12) 72%, rgba(17, 24, 22, .04) 100%),
    linear-gradient(180deg, rgba(247,248,244,.06), rgba(247,248,244,0));
}
.hero-content {
  position: relative;
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  color: white;
  padding-top: 38px;
}
.eyebrow {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: .8rem;
  text-transform: uppercase;
  font-weight: 700;
}
.hero h1 {
  margin: 0;
  max-width: 620px;
  font-family: var(--serif);
  font-size: 3.75rem;
  line-height: 1.08;
  font-weight: 700;
}
.hero-copy {
  max-width: 610px;
  margin: 22px 0 0;
  font-size: 1.12rem;
  color: rgba(255,255,255,.88);
}
.hero-actions,
.pill-row,
.filter-tabs {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}
.hero-actions { margin-top: 30px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 17px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  background: var(--panel);
  text-decoration: none;
  cursor: pointer;
  font-family: var(--sans);
  box-shadow: 0 8px 20px rgba(29, 40, 36, 0.06);
}
.btn.primary {
  background: #b99748;
  border-color: #b99748;
  color: #17140d;
  font-weight: 700;
}
.btn.ghost {
  color: white;
  background: rgba(255,255,255,.10);
  border-color: rgba(255,255,255,.38);
  box-shadow: none;
}
.btn.small {
  min-height: 38px;
  padding: 8px 12px;
}
.quick-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.trust-strip,
.library-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  background: var(--panel);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.trust-strip div,
.library-stats div {
  padding: 22px 24px;
  border-right: 1px solid var(--line);
}
.trust-strip span,
.library-stats span {
  display: block;
  color: var(--muted);
  font-size: .88rem;
}
.trust-strip strong,
.library-stats strong {
  display: block;
  margin: 4px 0 6px;
  color: var(--accent, var(--teal));
  font-family: var(--serif);
  font-size: 1.2rem;
}
.trust-strip p {
  margin: 0;
  color: var(--muted);
  font-size: .94rem;
}
.library-stats {
  grid-template-columns: repeat(5, 1fr);
}
.library-stats strong {
  font-size: 1.8rem;
}
.quick-stats div {
  padding: 22px 24px;
  border-right: 1px solid var(--line);
}
.quick-stats strong {
  display: block;
  font-size: 1.65rem;
  font-family: var(--serif);
}
.quick-stats span {
  color: var(--muted);
  font-size: .92rem;
}
.band {
  padding: 76px max(24px, calc((100vw - 1180px) / 2));
}
.split {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(300px, .95fr);
  gap: 46px;
  align-items: center;
}
h1, h2, h3, p { overflow-wrap: anywhere; }
h2 {
  margin: 0 0 18px;
  font-size: 2.3rem;
  line-height: 1.22;
  font-family: var(--serif);
}
h3 {
  margin: 0 0 10px;
  font-size: 1.18rem;
  line-height: 1.35;
  font-family: var(--serif);
}
.portrait {
  margin: 0;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
}
.portrait img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}
.portrait.large img { aspect-ratio: 3 / 4; }
.portrait figcaption {
  padding: 12px 14px;
  color: var(--muted);
  font-size: .9rem;
}
.pill-row span,
.tag-cloud span {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 10px;
  background: var(--panel);
  color: #35423d;
  font-size: .9rem;
}
.section-head {
  max-width: 760px;
  margin-bottom: 28px;
}
.section-head.with-action {
  max-width: none;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
}
.service-grid,
.blog-grid,
.feature-grid,
.answer-grid,
.entity-grid,
.proof-grid,
.decision-grid,
.mini-grid {
  display: grid;
  gap: 16px;
}
.service-grid {
  grid-template-columns: repeat(5, 1fr);
}
.service-card,
.blog-card,
.feature-grid > div,
.entity-grid > div,
.proof-grid > div,
.decision-grid > div,
.mini-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-top: 3px solid var(--accent, var(--gold));
  border-radius: 8px;
  padding: 22px;
  min-width: 0;
  box-shadow: 0 10px 30px rgba(29, 40, 36, 0.045);
}
.service-card span,
.category-dot,
.proof-grid span,
.decision-grid span {
  display: inline-flex;
  color: var(--accent, var(--gold));
  font-weight: 700;
  margin-bottom: 12px;
}
.service-card a,
.text-link {
  color: var(--teal);
  font-weight: 700;
  text-decoration: none;
}
.advisor-band {
  background: var(--wash);
}
.advisor {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 22px;
  box-shadow: var(--shadow);
}
label {
  display: grid;
  gap: 6px;
  margin-bottom: 14px;
  font-weight: 700;
}
input, select, textarea {
  width: 100%;
  border: 1px solid #ccd5ce;
  border-radius: 8px;
  background: var(--panel);
  padding: 11px 12px;
  color: var(--ink);
}
.search-panel,
.sort-panel,
.contact-builder {
  display: grid;
  gap: 8px;
}
.search-panel .btn {
  justify-self: start;
}
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}
.form-note {
  margin: 0;
  color: var(--muted);
  font-size: .92rem;
}
.advisor-result,
.message-output {
  display: block;
  width: 100%;
  min-height: 96px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: #f7f8f4;
  padding: 14px;
  color: #2d3834;
}
.adult-home-band,
.assessment-band {
  background: var(--wash);
}
.adult-hero {
  background: linear-gradient(135deg, #1d2824 0%, #2b403a 100%);
}
.route-grid,
.article-ladder,
.choice-grid,
.lesson-roadmap {
  display: grid;
  gap: 14px;
}
.route-grid {
  grid-template-columns: repeat(3, 1fr);
}
.route-tile,
.route-card,
.lesson-roadmap > div {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 18px;
  box-shadow: 0 10px 26px rgba(29, 40, 36, 0.04);
}
.route-tile span,
.route-card .step,
.lesson-roadmap span {
  display: inline-block;
  color: var(--burgundy);
  font-weight: 700;
  margin-bottom: 8px;
}
.route-tile strong,
.route-card strong,
.lesson-roadmap strong {
  display: block;
  line-height: 1.35;
}
.route-tile p,
.route-card p,
.lesson-roadmap p {
  margin-bottom: 0;
  color: var(--muted);
}
.article-ladder {
  grid-template-columns: repeat(5, 1fr);
}
.route-card {
  min-height: 260px;
  color: inherit;
  text-decoration: none;
  display: flex;
  flex-direction: column;
}
.route-card small {
  color: var(--teal);
  font-weight: 700;
  margin-bottom: 8px;
}
.route-card p {
  flex: 1;
}
.instrument-picker.answer-grid {
  grid-template-columns: repeat(4, 1fr);
}
.instrument-picker .answer-box {
  border-top: 4px solid var(--accent);
}
.assessment-layout {
  align-items: start;
}
.adult-assessment {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 22px;
  box-shadow: var(--shadow);
}
.choice-group {
  border-bottom: 1px solid var(--line);
  padding-bottom: 16px;
  margin-bottom: 16px;
}
.choice-group > p {
  margin: 0 0 10px;
  font-weight: 700;
}
.choice-grid {
  grid-template-columns: repeat(2, 1fr);
}
.choice-card {
  grid-template-columns: 20px 1fr;
  align-items: start;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 12px;
  margin: 0;
  font-weight: 500;
  cursor: pointer;
}
.choice-card input {
  width: auto;
  margin-top: 6px;
  accent-color: var(--teal);
}
.choice-card span,
.choice-card small {
  grid-column: 2;
}
.choice-card span {
  font-weight: 700;
  line-height: 1.35;
}
.choice-card small {
  color: var(--muted);
}
.choice-card:has(input:checked) {
  border-color: var(--teal);
  background: #edf6f2;
}
.assessment-result {
  border: 1px solid var(--teal);
  border-radius: 8px;
  background: #f5fbf8;
  padding: 16px;
}
.assessment-result strong {
  display: block;
  margin-bottom: 8px;
  color: var(--teal);
}
.assessment-result p {
  margin: 0 0 8px;
}
.assessment-result a {
  color: var(--burgundy);
  font-weight: 700;
  text-decoration: none;
}
.adult-assessment [data-reset-adult] {
  margin-top: 12px;
}
.lesson-roadmap {
  grid-template-columns: repeat(4, 1fr);
}
.dark-band .lesson-roadmap > div {
  background: rgba(255,255,255,.09);
  border-color: rgba(255,255,255,.16);
}
.dark-band .lesson-roadmap p {
  color: rgba(255,255,255,.74);
}
.blog-route-band {
  padding-bottom: 0;
}
.route-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-radius: 8px;
  background: linear-gradient(135deg, #1d2824 0%, #314840 100%);
  color: white;
  padding: 28px;
}
.route-banner h2,
.route-banner p {
  margin: 0;
}
.route-banner p:not(.eyebrow) {
  color: rgba(255,255,255,.78);
}
.final-actions {
  margin-top: 28px;
}
.blog-grid {
  grid-template-columns: repeat(3, 1fr);
}
.blog-card {
  display: flex;
  flex-direction: column;
  min-height: 280px;
  overflow: hidden;
}
.blog-card picture {
  display: block;
  margin: -22px -22px 18px;
}
.blog-card-image {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background: #eef3ef;
  border-bottom: 1px solid var(--line);
}
.blog-card h3 a {
  text-decoration: none;
}
.blog-card p {
  color: var(--muted);
  flex: 1;
}
.card-meta {
  display: flex;
  justify-content: flex-start;
  flex-wrap: wrap;
  gap: 10px;
  color: var(--muted);
  font-size: .86rem;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}
.ai-band,
.dark-band {
  background: linear-gradient(135deg, #1d2824 0%, #263a35 100%);
  color: white;
}
.dark-band .eyebrow,
.ai-band .eyebrow { color: #ddc47e; }
.answer-grid {
  grid-template-columns: repeat(3, 1fr);
}
.answer-box {
  background: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 22px;
  box-shadow: 0 10px 28px rgba(29, 40, 36, 0.035);
}
.answer-box span {
  display: inline-block;
  margin-bottom: 10px;
  color: var(--teal);
  font-weight: 700;
}
.article-note-grid,
.practice-cards,
.trust-grid,
.media-brief {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 22px 0;
}
.practice-cards,
.trust-grid,
.media-brief {
  grid-template-columns: repeat(2, 1fr);
}
.article-note-grid > div,
.practice-cards > div,
.trust-grid > div,
.media-brief > div,
.soft-cta {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f7f8f4;
  padding: 16px;
}
.article-note-grid span,
.media-brief span {
  display: block;
  color: var(--teal);
  font-size: .82rem;
  font-weight: 700;
  margin-bottom: 4px;
}
.article-note-grid p,
.practice-cards p,
.trust-grid p,
.media-brief p {
  margin: 0;
}
.media-brief {
  grid-template-columns: 1fr;
}
.media-brief > div {
  background: var(--panel);
}
.soft-cta {
  margin: 34px 0;
  background: linear-gradient(135deg, #edf6f2 0%, #fbfaf4 100%);
  border-color: #cbdcd3;
}
.soft-cta h2 {
  margin-top: 0;
}
.page-hero {
  padding: 84px max(24px, calc((100vw - 1180px) / 2)) 56px;
  background: linear-gradient(135deg, #1d2824 0%, #263a35 100%);
  color: white;
}
.compact-hero h1 {
  max-width: 880px;
  margin: 0 0 16px;
  font-size: 3.05rem;
  line-height: 1.14;
  font-family: var(--serif);
}
.compact-hero p:not(.eyebrow) {
  max-width: 760px;
  color: rgba(255,255,255,.82);
  font-size: 1.08rem;
}
.timeline {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 24px;
}
.timeline div {
  display: grid;
  gap: 4px;
  padding: 16px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.timeline strong { color: var(--burgundy); }
.feature-grid,
.entity-grid {
  grid-template-columns: repeat(4, 1fr);
}
.dark-band .feature-grid > div,
.dark-band .entity-grid > div {
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.16);
}
.course-list {
  display: grid;
  gap: 18px;
}
.course-row {
  display: grid;
  grid-template-columns: minmax(0, .95fr) minmax(300px, 1.05fr);
  gap: 28px;
  padding: 28px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.check-list {
  padding: 0;
  margin: 0;
  list-style: none;
  display: grid;
  gap: 10px;
}
.check-list li {
  position: relative;
  padding-left: 26px;
}
.check-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--teal);
  font-weight: 700;
}
.practice-band { background: #f6f0f2; }
.proof-band,
.library-route-band,
.privacy-band {
  background: #fbfaf4;
}
.decision-band,
.faq-band {
  background: var(--wash);
}
.proof-grid,
.decision-grid {
  grid-template-columns: repeat(4, 1fr);
}
.decision-grid {
  grid-template-columns: repeat(3, 1fr);
}
.practice-planner {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 22px;
}
.practice-planner label {
  grid-template-columns: 22px 1fr;
  align-items: start;
  font-weight: 500;
}
.practice-planner input {
  width: 18px;
  margin-top: 5px;
}
.blog-tools {
  padding-bottom: 24px;
  display: grid;
  grid-template-columns: minmax(260px, 420px) minmax(180px, 240px);
  gap: 22px;
  align-items: end;
}
.blog-tools .filter-tabs {
  grid-column: 1 / -1;
}
.blog-count {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--muted);
  font-size: .94rem;
}
.filter-tabs button {
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--panel);
  padding: 9px 13px;
  cursor: pointer;
  color: var(--ink);
}
.filter-tabs button span {
  color: var(--muted);
  font-size: .82rem;
}
.filter-tabs button.active {
  background: var(--ink);
  color: white;
}
.filter-tabs button.active span {
  color: rgba(255,255,255,.72);
}
.empty-state {
  text-align: center;
  padding: 36px;
  color: var(--muted);
}
.article-hero {
  background: linear-gradient(135deg, #1d2824 0%, #243833 100%);
  color: white;
  padding: 68px max(24px, calc((100vw - 980px) / 2)) 54px;
}
.article-hero-inner h1 {
  margin: 0 0 16px;
  font-size: 3rem;
  line-height: 1.18;
  font-family: var(--serif);
}
.article-lead {
  max-width: 780px;
  color: rgba(255,255,255,.82);
  font-size: 1.08rem;
}
.article-meta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  color: rgba(255,255,255,.72);
  font-size: .92rem;
}
.back-link {
  display: inline-block;
  margin-bottom: 24px;
  color: #ddc47e;
  text-decoration: none;
}
.breadcrumb {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 18px;
  color: rgba(255,255,255,.68);
  font-size: .9rem;
}
.breadcrumb a {
  color: #ddc47e;
  text-decoration: none;
}
.article-shell {
  display: grid;
  grid-template-columns: 240px minmax(0, 760px);
  gap: 42px;
  align-items: start;
  padding: 56px max(24px, calc((100vw - 1080px) / 2));
}
.article-side {
  position: sticky;
  top: 92px;
  display: grid;
  gap: 8px;
  background: rgba(255,255,251,.92);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 16px;
  box-shadow: 0 10px 28px rgba(29, 40, 36, 0.035);
}
.article-side a {
  text-decoration: none;
  color: #34403b;
}
.side-title {
  margin: 0 0 6px;
  font-weight: 700;
}
.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}
.article-body {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 36px;
  box-shadow: 0 12px 34px rgba(29, 40, 36, 0.045);
}
.article-photo {
  width: 100%;
  max-width: 520px;
  margin: 22px auto 30px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f7f8f4;
  overflow: hidden;
}
.article-photo {
  background: var(--sumi);
}
.article-photo picture {
  display: block;
}
.article-photo img {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  display: block;
}
.article-photo figcaption {
  padding: 12px 16px;
  color: var(--muted);
  font-size: .9rem;
  border-top: 1px solid var(--line);
  background: var(--panel);
}
.article-photo figcaption {
  color: #5c5750;
}
.article-body h2 {
  margin-top: 36px;
  font-size: 1.75rem;
}
.author-box {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  margin: 30px 0;
  padding: 18px;
  border: 1px solid #cbdcd3;
  border-radius: 8px;
  background: #edf6f2;
}
.author-box span {
  display: block;
  color: var(--teal);
  font-weight: 700;
  font-size: .86rem;
}
.author-box strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.15rem;
}
.author-box p {
  margin: 6px 0 0;
  color: #3c4944;
}
.faq-list {
  display: grid;
  gap: 10px;
}
.faq-list details {
  background: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px 16px;
}
.dark-band .faq-list details {
  background: rgba(255,255,255,.08);
  color: white;
  border-color: rgba(255,255,255,.18);
}
.faq-list summary {
  cursor: pointer;
  font-weight: 700;
}
.related-band { padding-top: 20px; }
.mini-grid {
  grid-template-columns: repeat(3, 1fr);
}
.mini-card {
  text-decoration: none;
}
.mini-card span {
  color: var(--teal);
  font-weight: 700;
  font-size: .86rem;
}
.site-footer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  padding: 34px max(24px, calc((100vw - 1180px) / 2));
  background: var(--sumi);
  color: rgba(255,255,255,.78);
}
.footer-title {
  margin: 0;
  color: white;
  font-weight: 700;
}
.site-footer a { color: #ddc47e; }
.mobile-sticky-cta {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

@media (max-width: 1020px) {
  .service-grid,
  .blog-grid,
  .answer-grid,
  .article-note-grid,
  .practice-cards,
  .trust-grid,
  .route-grid,
  .article-ladder,
  .instrument-picker.answer-grid,
  .lesson-roadmap,
  .feature-grid,
  .entity-grid,
  .proof-grid,
  .decision-grid,
  .library-stats,
  .mini-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .split,
  .course-row,
  .article-shell,
  .blog-tools,
  .route-banner {
    grid-template-columns: 1fr;
  }
  .route-banner {
    display: grid;
  }
  .article-side { position: static; }
}

@media (max-width: 760px) {
  .site-header {
    padding: 12px 16px;
  }
  .nav-toggle { display: inline-grid; place-items: center; }
  .main-nav {
    position: absolute;
    top: 68px;
    left: 16px;
    right: 16px;
    display: none;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 10px;
    box-shadow: var(--shadow);
    justify-content: stretch;
  }
  .main-nav.open {
    display: grid;
  }
  .main-nav a {
    width: 100%;
    padding: 12px 14px;
    border-radius: 8px;
  }
  .brand small { display: none; }
  .hero {
    min-height: 470px;
    height: 60vh;
    background-position: 62% center;
  }
  .hero-overlay {
    background: linear-gradient(90deg, rgba(17,24,22,.78), rgba(17,24,22,.48));
  }
  .hero h1 { font-size: 2.38rem; }
  .hero-copy { font-size: 1rem; }
  .service-grid,
  .blog-grid,
  .answer-grid,
  .article-note-grid,
  .practice-cards,
  .trust-grid,
  .route-grid,
  .article-ladder,
  .choice-grid,
  .instrument-picker.answer-grid,
  .lesson-roadmap,
  .feature-grid,
  .entity-grid,
  .proof-grid,
  .decision-grid,
  .trust-strip,
  .library-stats,
  .mini-grid,
  .timeline,
  .site-footer {
    grid-template-columns: 1fr;
  }
  .header-cta {
    display: none;
  }
  .trust-strip div,
  .library-stats div {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
  .quick-stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .quick-stats div {
    border-bottom: 1px solid var(--line);
    padding: 18px 22px;
  }
  .band { padding-top: 54px; padding-bottom: 54px; }
  h2 { font-size: 1.9rem; }
  .compact-hero h1,
  .article-hero-inner h1 {
    font-size: 2rem;
  }
  .page-hero {
    padding-top: 56px;
    padding-bottom: 38px;
  }
  .article-hero {
    padding-top: 56px;
    padding-bottom: 42px;
  }
  .article-lead {
    font-size: 1rem;
    line-height: 1.78;
  }
  .article-shell {
    padding-top: 24px;
  }
  .article-side {
    position: static;
    display: flex;
    gap: 8px;
    overflow-x: auto;
    margin: 0 -24px 22px;
    padding: 10px 24px;
    border-left: 0;
    border-right: 0;
    border-radius: 0;
    box-shadow: none;
    scroll-snap-type: x proximity;
  }
  .article-side .side-title,
  .article-side .tag-cloud {
    display: none;
  }
  .article-side a {
    flex: 0 0 auto;
    scroll-snap-align: start;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--panel);
    padding: 6px 10px;
    font-size: .92rem;
  }
  .article-body {
    padding: 22px;
  }
  .author-box {
    display: grid;
  }
  .article-body h2 {
    font-size: 1.55rem;
  }
  .article-photo {
    max-width: 100%;
  }
  .section-head.with-action {
    display: block;
  }
  .mobile-sticky-cta {
    position: fixed;
    left: 16px;
    right: 16px;
    bottom: 14px;
    z-index: 30;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 46px;
    border-radius: 8px;
    background: #b99748;
    color: #17140d;
    font-weight: 700;
    text-decoration: none;
    box-shadow: 0 14px 34px rgba(29, 40, 36, .22);
  }
  body {
    padding-bottom: 74px;
  }
}
"""


def js() -> str:
    return r"""
(function () {
  const navToggle = document.querySelector("[data-nav-toggle]");
  const nav = document.querySelector("[data-nav]");
  if (navToggle && nav) {
    navToggle.addEventListener("click", () => {
      const open = nav.classList.toggle("open");
      navToggle.setAttribute("aria-expanded", open ? "true" : "false");
    });
    nav.querySelectorAll("a").forEach((link) => {
      link.addEventListener("click", () => {
        nav.classList.remove("open");
        navToggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  const profile = {
    "長笛": "建議先做音色與氣息評估，再按程度安排長音、音階、曲目與考級路線。",
    "笛子": "建議先檢查口風、笛膜與筒音概念，再安排民歌句法和技巧練習。",
    "空靈鼓": "建議從左右手、節奏和調式開始，再加入即興、合奏或親子活動設計。",
    "簫": "建議先建立穩定空音、長音與口風方向，再進入古曲句法和音色層次。",
    "考級": "建議先做模擬診斷，列出曲目、音階、視奏、聽覺與伴奏時間表。"
  };

  document.querySelectorAll("[data-advisor]").forEach((form) => {
    const output = form.querySelector("[data-advisor-result]");
    const update = () => {
      const data = new FormData(form);
      const instrument = data.get("instrument");
      const level = data.get("level");
      const goal = data.get("goal");
      const message = `${instrument} · ${level} · ${goal}：${profile[instrument]} 首四堂應以「診斷、基本功、短曲應用、回家練習表」為主。`;
      output.value = message;
      output.textContent = message;
    };
    form.addEventListener("change", update);
    update();
  });

  document.querySelectorAll("[data-adult-assessment]").forEach((form) => {
    const result = form.querySelector("[data-adult-result]");
    const articles = {
      "長笛": { href: "blog/flute-13-flute.html", title: "成人學長笛：時間少也能進步的練習設計" },
      "笛子": { href: "blog/dizi-14-dizi.html", title: "成人學笛子：由零開始也能吹出穩定音色" },
      "簫": { href: "blog/xiao-01-xiao-xiao.html", title: "初識簫：為甚麼簫的第一個音要慢慢找" },
      "空靈鼓": { href: "blog/tongue-drum-05-tongue-drum.html", title: "空靈鼓與安靜練習：聲音放鬆但不要失去結構" }
    };
    const advice = {
      "長笛": "你的選項較接近長笛路線。第一階段應先處理口型、呼吸、長音和短句，不用急着吹很長的曲。",
      "笛子": "你的選項較接近笛子路線。第一階段應先處理口風、笛膜和筒音，讓聲音穩定後再學民樂句法。",
      "簫": "你的選項較接近簫路線。第一階段應先處理長音、口風方向、手指放鬆和慢句；如果主要限制是深夜聲量，仍要再看住家環境。",
      "空靈鼓": "你的選項較接近空靈鼓路線。第一階段可以由左右手、拍點和簡單音型開始；如果多數只能晚上練，較容易用輕觸和短循環控制聲量。"
    };
    const update = () => {
      const data = new FormData(form);
      const score = { "長笛": 0, "笛子": 0, "簫": 0, "空靈鼓": 0 };
      const add = (name, points) => { score[name] += points; };

      switch (data.get("sound")) {
        case "bright": add("長笛", 4); add("笛子", 1); break;
        case "folk": add("笛子", 4); add("簫", 1); break;
        case "calm": add("簫", 4); add("空靈鼓", 1); break;
        case "relax": add("空靈鼓", 4); add("簫", 1); break;
      }
      switch (data.get("time")) {
        case "short": add("空靈鼓", 2); add("簫", 1); break;
        case "steady": add("長笛", 2); add("笛子", 2); break;
        case "weekend": add("長笛", 1); add("笛子", 1); add("空靈鼓", 1); break;
        case "unknown": add("空靈鼓", 2); add("簫", 1); break;
      }
      switch (data.get("goal")) {
        case "exam": add("長笛", 3); add("笛子", 2); break;
        case "stage": add("長笛", 2); add("笛子", 2); break;
        case "relax": add("空靈鼓", 3); add("簫", 2); break;
        default: add("長笛", 1); add("笛子", 1); add("簫", 1); add("空靈鼓", 1);
      }
      if (data.get("volume") === "quiet") {
        add("空靈鼓", 3);
        add("簫", 1);
      } else {
        add("長笛", 1);
        add("笛子", 1);
      }

      const ranked = Object.entries(score).sort((a, b) => b[1] - a[1]);
      const first = ranked[0][0];
      const second = ranked[1] && ranked[0][1] === ranked[1][1] ? ranked[1][0] : "";
      const label = second ? `${first} 或 ${second}` : first;
      const article = articles[first];
      result.innerHTML = `<strong>較接近的學習方向：${label}</strong>
        <p>${advice[first]}</p>
        <p>查詢時可以直接說：「我是成人初學者，較想了解${label}，每週練習時間和音量限制如下，希望張老師先幫我判斷第一堂課方向。」</p>
        <a href="${article.href}">先讀：${article.title} →</a>`;
    };
    form.addEventListener("change", update);
    const reset = form.querySelector("[data-reset-adult]");
    if (reset) {
      reset.addEventListener("click", () => {
        form.reset();
        update();
      });
    }
    update();
  });

  const posts = window.BLOG_POSTS || [];
  const list = document.querySelector("[data-blog-list]");
  const empty = document.querySelector("[data-empty]");
  const search = document.querySelector("#blogSearch");
  const clearSearch = document.querySelector("[data-clear-blog-search]");
  const filters = document.querySelector("[data-blog-filters]");
  const sort = document.querySelector("[data-blog-sort]");
  const count = document.querySelector("[data-blog-count]");
  let activeFilter = "全部";

  function card(post) {
    return `<article class="blog-card" data-category="${post.category}">
      <picture>
        <source srcset="${post.imageWebp}" type="image/webp">
        <img class="blog-card-image" src="${post.image}" alt="${post.imageAlt}" loading="lazy" decoding="async" width="1200" height="675">
      </picture>
      <span class="category-dot" style="--accent:${post.color}">${post.category}</span>
      <h3><a href="${post.url}">${post.title}</a></h3>
      <p>${post.excerpt}</p>
      <div class="card-meta"><span>${post.date}</span><span>${post.readTime}</span><span>${post.level}</span></div>
    </article>`;
  }

  function renderPosts() {
    if (!list) return;
    const q = (search && search.value ? search.value : "").trim().toLowerCase();
    const filtered = posts.filter((post) => {
      const matchCategory = activeFilter === "全部" || post.category === activeFilter;
      const haystack = `${post.title} ${post.category} ${post.excerpt} ${(post.keywords || []).join(" ")}`.toLowerCase();
      const matchQuery = !q || haystack.includes(q);
      return matchCategory && matchQuery;
    });
    const sorted = filtered.slice().sort((a, b) => {
      const mode = sort ? sort.value : "recommended";
      if (mode === "latest") return b.date.localeCompare(a.date);
      if (mode === "category") return a.category.localeCompare(b.category, "zh-Hant") || a.number - b.number;
      return a.order - b.order;
    });
    list.innerHTML = sorted.map(card).join("");
    if (empty) empty.hidden = filtered.length !== 0;
    if (count) {
      const label = activeFilter === "全部" ? "全部分類" : activeFilter;
      count.textContent = `顯示 ${filtered.length} / ${posts.length} 篇 · ${label}`;
    }
  }

  if (filters) {
    filters.addEventListener("click", (event) => {
      const button = event.target.closest("button[data-filter]");
      if (!button) return;
      filters.querySelectorAll("button").forEach((item) => item.classList.remove("active"));
      button.classList.add("active");
      activeFilter = button.dataset.filter;
      renderPosts();
    });
  }
  if (search) {
    search.addEventListener("input", () => {
      const url = new URL(location.href);
      const value = search.value.trim();
      if (value) url.searchParams.set("q", value);
      else url.searchParams.delete("q");
      history.replaceState(null, "", url);
      renderPosts();
    });
  }
  if (clearSearch && search) {
    clearSearch.addEventListener("click", () => {
      search.value = "";
      const url = new URL(location.href);
      url.searchParams.delete("q");
      history.replaceState(null, "", url);
      renderPosts();
      search.focus();
    });
  }
  if (sort) sort.addEventListener("change", renderPosts);
  if (search) {
    const params = new URLSearchParams(location.search);
    const initialQuery = params.get("q");
    if (initialQuery) search.value = initialQuery;
  }
  renderPosts();

  document.querySelectorAll("[data-practice]").forEach((box, boxIndex) => {
    const key = `teacher-zhang-practice-${boxIndex}`;
    const inputs = Array.from(box.querySelectorAll("input[type='checkbox']"));
    const saved = JSON.parse(localStorage.getItem(key) || "[]");
    inputs.forEach((input, index) => {
      input.checked = Boolean(saved[index]);
      input.addEventListener("change", () => {
        localStorage.setItem(key, JSON.stringify(inputs.map((item) => item.checked)));
      });
    });
    const reset = box.querySelector("[data-reset-practice]");
    if (reset) {
      reset.addEventListener("click", () => {
        inputs.forEach((item) => { item.checked = false; });
        localStorage.removeItem(key);
      });
    }
  });

  document.querySelectorAll("[data-contact-builder]").forEach((form) => {
    const button = form.querySelector("[data-build-message]");
    const output = form.querySelector("[data-message-output]");
    const copy = form.querySelector("[data-copy-message]");
    const status = form.querySelector("[data-copy-status]");
    button.addEventListener("click", () => {
      const data = new FormData(form);
      const name = data.get("name") || "學生/家長";
      const instrument = data.get("instrument");
      const level = data.get("level") || "未填寫";
      const goal = data.get("goal") || "希望先由張老師評估";
      output.value = `張老師你好，我是${name}。我想查詢${instrument}課程，目前程度是：${level}。學習目標：${goal}。想了解合適的上課安排，謝謝。`;
      output.focus();
      output.select();
      if (status) status.textContent = "訊息已生成，可複製後到正式聯絡方式使用。";
    });
    if (copy) {
      copy.addEventListener("click", async () => {
        if (!output.value.trim()) button.click();
        try {
          await navigator.clipboard.writeText(output.value);
          if (status) status.textContent = "已複製，可貼到正式聯絡訊息。";
        } catch (error) {
          output.focus();
          output.select();
          if (status) status.textContent = "已選取文字，可手動複製。";
        }
      });
    }
  });
})();
"""


def blog_index_js() -> str:
    data = [
        {
            "order": index,
            "title": p["title"],
            "category": p["category"],
            "url": p["url"],
            "excerpt": p["excerpt"],
            "keywords": p["keywords"],
            "date": p["date"],
            "readTime": p["readTime"],
            "level": p["level"],
            "number": p["number"],
            "color": p["color"],
            "image": article_cover_path(p),
            "imageWebp": article_cover_webp_path(p),
            "imageAlt": article_cover_alt(p),
        }
        for index, p in enumerate(POSTS)
    ]
    return "window.BLOG_POSTS = " + json.dumps(data, ensure_ascii=False, indent=2) + ";\n"


def sitemap() -> str:
    urls = ["", "about.html", "courses.html", "adult-beginner.html", "blog.html", "ai-seo-hub.html", "contact.html"] + [
        p["url"] for p in POSTS
    ]
    entries = []
    for url in urls:
        loc = BASE_URL if not url else f"{BASE_URL}/{url}"
        post = next((item for item in POSTS if item["url"] == url), None)
        lastmod = TODAY.isoformat()
        changefreq = "weekly" if url in ("", "blog.html", "ai-seo-hub.html") or post else "monthly"
        priority = "1.0" if url == "" else ("0.8" if not post else "0.7")
        image_markup = ""
        if post:
            image_markup = (
                f"<image:image><image:loc>{e(absolute_url(article_cover_path(post)))}</image:loc>"
                f"<image:title>{e(post['title'])}</image:title></image:image>"
            )
        entries.append(
            f"  <url><loc>{e(loc)}</loc><lastmod>{lastmod}</lastmod><changefreq>{changefreq}</changefreq><priority>{priority}</priority>{image_markup}</url>"
        )
    return (
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
        "<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\" "
        "xmlns:image=\"http://www.google.com/schemas/sitemap-image/1.1\">\n"
        + "\n".join(entries)
        + "\n</urlset>\n"
    )


