def robots_txt() -> str:
    lines = [
        "# Public learning content for search engines and AI answer engines.",
        "User-agent: *",
        "Allow: /",
        "",
        "# Explicitly allow major AI search/citation crawlers.",
    ]
    for bot in AI_SEARCH_BOTS:
        lines.extend([f"User-agent: {bot}", "Allow: /", ""])
    lines.append(f"Sitemap: {BASE_URL}/sitemap.xml")
    return "\n".join(lines).rstrip() + "\n"


def csv_cell(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'


def redirect_map_csv() -> str:
    rows = ["old_path,target_url,status,reason"]
    for old_path, target_path, reason in REDIRECTS:
        rows.append(",".join([csv_cell(old_path), csv_cell(absolute_url(target_path)), "301", csv_cell(reason)]))
    return "\n".join(rows) + "\n"


def redirect_rules_txt() -> str:
    lines = [
        "# 301 redirects for static hosting platforms that support Netlify-style _redirects.",
        "# Review these against the live sitemap before deployment.",
    ]
    for old_path, target_path, _reason in REDIRECTS:
        lines.append(f"{old_path} {target_path} 301")
    return "\n".join(lines) + "\n"


def deployment_checklist_md() -> str:
    return f"""# SEO / GEO / AIEO deployment checklist

Updated: {TODAY.isoformat()}

## Before upload

- Upload every generated HTML file, `assets/`, `sitemap.xml`, `robots.txt`, `llms.txt`, `site.webmanifest`, and the article cover images.
- Apply the 301 rules in `deployment/redirect-map.csv` or `deployment/_redirects` before replacing the old site.
- Keep old high-value URLs live only as 301 redirects; do not leave them as duplicate pages.

## After upload

- Confirm these URLs return 200: `{BASE_URL}/`, `{BASE_URL}/sitemap.xml`, `{BASE_URL}/robots.txt`, `{BASE_URL}/llms.txt`, `{BASE_URL}/ai-seo-hub.html`.
- Confirm representative articles return 200, for example `{BASE_URL}/blog/flute-01-flute.html`.
- Submit `{BASE_URL}/sitemap.xml` in Google Search Console and Bing Webmaster Tools.
- Use Bing Webmaster Tools AI Performance after indexing to monitor AI citations and grounding queries.
- Check that old URLs such as `{BASE_URL}/aboutme` and `{BASE_URL}/flute-class` return 301 to the mapped new pages.

## Content QA

- For the 20 highest commercial-intent articles, verify the first answer block gives a direct 50-80 word answer.
- Keep entity names consistent: `{AUTHOR}`, `{SITE_NAME}`, `Oliver Flute`, `香港`, `屯門`, `新界西`.
- When copying articles to another CMS, upload images there and rewrite `src` / `srcset`; the static HTML image paths do not move images automatically.
"""


def manifest_json() -> str:
    data = {
        "name": SITE_NAME,
        "short_name": "張老師音樂",
        "description": "張老師 Oliver Cheung 的長笛、笛子、簫、空靈鼓與考級內容中心。",
        "lang": "zh-Hant-HK",
        "start_url": "index.html",
        "scope": "./",
        "display": "standalone",
        "background_color": "#f7f8f4",
        "theme_color": "#1d2824",
        "icons": [
            {
                "src": "assets/images/brand-mark-original.png",
                "sizes": "512x512",
                "type": "image/png",
                "purpose": "any maskable",
            }
        ],
    }
    return json.dumps(data, ensure_ascii=False, indent=2) + "\n"


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")


def generate_webp_assets() -> None:
    try:
        from PIL import Image
    except Exception:
        return

    candidates = ["assets/images/concert-studio-hero.png"] + [article_cover_path(post) for post in POSTS]
    for rel in candidates:
        source = ROOT / rel
        if not source.exists():
            continue
        target = ROOT / webp_path(rel)
        if target.exists() and target.stat().st_mtime >= source.stat().st_mtime:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        with Image.open(source) as img:
            if img.mode not in ("RGB", "RGBA"):
                img = img.convert("RGB")
            if img.mode == "RGBA":
                bg = Image.new("RGB", img.size, "#f7f8f4")
                bg.paste(img, mask=img.getchannel("A"))
                img = bg
            img.save(target, "WEBP", quality=78, method=6)


def build() -> None:
    image_prompts = load_article_image_prompts()
    regenerate_covers = os.environ.get("REGENERATE_ARTICLE_COVERS") == "1"
    write("assets/css/styles.css", css())
    write("assets/js/site.js", js())
    write("assets/js/blog-index.js", blog_index_js())
    for post in POSTS:
        write(article_image_path(post), article_svg(post))
        cover_file = ROOT / article_cover_path(post)
        if regenerate_covers or not cover_file.exists():
            generate_article_cover(post, image_prompts.get(post["url"], ""))
    generate_webp_assets()
    write("index.html", home_page())
    write("about.html", about_page())
    write("courses.html", courses_page())
    write("adult-beginner.html", adult_beginner_page())
    write("blog.html", blog_page())
    write("ai-seo-hub.html", hub_page())
    write("contact.html", contact_page())
    write("404.html", not_found_page())
    by_category = {}
    for post in POSTS:
        by_category.setdefault(post["category"], []).append(post)
    for post in POSTS:
        pool = [p for p in by_category[post["category"]] if p["id"] != post["id"]]
        related = (pool + POSTS)[:3]
        write(post["url"], article_html(post, related))
    write("sitemap.xml", sitemap())
    write("robots.txt", robots_txt())
    write("llms.txt", llms_txt())
    write("deployment/redirect-map.csv", redirect_map_csv())
    write("deployment/_redirects", redirect_rules_txt())
    write("deployment/deployment-checklist.md", deployment_checklist_md())
    write("site.webmanifest", manifest_json())
    write(
        "README.md",
        f"""# {SITE_NAME}

本機升級版網站，基於 https://www.oliverflute.com/ 的張老師音樂品牌建立。

## 內容

- 首頁、關於張老師、課程、成人初學者入口、文章資料庫、學習指南、查詢頁
- 100篇博客文章：長笛、笛子、空靈鼓、簫、考級各20篇
- 本機互動功能：文章搜尋/篩選、課程建議器、成人查詢前整理、練習清單、查詢訊息產生器
- 搜尋友善架構：每篇文章獨立頁面、Meta description、JSON-LD、FAQ、sitemap.xml、llms.txt、site.webmanifest
- 站內搜尋支援 `blog.html?q=關鍵字`，並已加入 WebSite SearchAction 結構化資料
- 圖片效能：文章封面及首頁 hero 生成 WebP，保留 JPG/PNG 回退
- AI 搜尋資產：`robots.txt` 明確允許主要 AI 搜尋/答案 bot，`llms.txt` 提供主題集群、引用建議和文章清單
- 部署遷移資產：`deployment/redirect-map.csv`、`deployment/_redirects`、`deployment/deployment-checklist.md`

## 圖片來源

- 長笛實物相片：Pexels / Jean-Paul Wright，https://www.pexels.com/photo/close-up-shot-of-silver-flutes-7238908/
- 竹製吹管實物相片：Unsplash / Seven Colors，https://unsplash.com/photos/a-close-up-of-three-wooden-pipes-on-a-bamboo-mat-gDBRWWh6dOc
- 空靈鼓實物相片：Pexels / Darcy Lawrey，https://www.pexels.com/photo/close-up-photo-of-brown-instrument-with-blue-sticks-848651/
- 節拍器實物相片：Pexels / Pixabay，https://www.pexels.com/photo/black-and-red-electric-device-162550/
- 文章封面圖：本機為 100 篇文章各自生成 JPG / WebP 相片式封面，主要取材自樂器實物與練習物件，沒有老師樣貌或真人角色
- 原有 SVG 只保留為未使用的舊稿資產，不再作為文章封面或文章內插圖
- 所有封面圖已在文章 caption 標示為「實物相片式封面圖」及用途

## 預覽

直接打開 `index.html` 可預覽基本頁面。建議使用本機伺服器，圖片、manifest 和相對路徑較穩定：

```powershell
python -m http.server 8765 --bind 127.0.0.1
```

然後打開 http://127.0.0.1:8765/index.html

## 驗證

最終驗收紀錄在 `validation/final_acceptance_report.md`。
已提供 `tools/verify_site.cjs`，可檢查首頁、文章資料庫、文章頁、手機版導覽、圖片載入與水平溢出。驗證截圖會輸出到 `validation/`。
""",
    )


if __name__ == "__main__":
    build()
    print(f"Built {len(POSTS)} articles into {ROOT}")
